}

/* Interface theme picker (DESIGN.md 10.5): three buttons, the current one pressed. */
.cxx-settings-theme {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 0;
  border-bottom: 1px solid var(--cxx-line);
}

.cxx-settings-theme>div {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.cxx-settings-center .cxx-settings-theme button {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  min-width: 96px;
}

.cxx-settings-theme i {
  flex: none;
