.cxx-settings-theme [data-theme=red] i {
  background: var(--cxx-preview-red);
}

.cxx-settings-theme [data-theme=yellow] i {
  background: var(--cxx-preview-yellow);
}

.cxx-settings-theme [data-theme=night] i {
  background: var(--cxx-preview-night);
}

.cxx-settings-center .cxx-settings-theme button[aria-pressed=true] {
  border-color: var(--cxx-interactive);
  color: var(--cxx-interactive);
  box-shadow: inset 0 0 0 1px var(--cxx-interactive);
