globalThis.CxxStoryStyle="/* Shared UI roles, emitted into each document and Shadow Root by the card build. */
:root, :host {
  --cxx-ink: var(--cxx-theme-ink,#08080b);
  --cxx-panel: var(--cxx-theme-panel,#120a0d);
  --cxx-raised: var(--cxx-theme-raised,#211217);
  /* Existing opening book/card surfaces share this red tint. */
  --cxx-narrative-panel: #6a1820;
  --cxx-text: var(--cxx-theme-text,#e6e9e8);
  --cxx-muted: var(--cxx-theme-muted,#b5b8bd);
  --cxx-line: var(--cxx-theme-line,#71343f);
  --cxx-shadow: #000;
  /* Shared neutral scrim for modal surfaces. */
  --cxx-scrim: #06080b;
  --cxx-red: #f25964;
  --cxx-red-soft: #ffb5bc;
  --cxx-cyan: #6ecbd0;
  --cxx-cyan-soft: #b9e8eb;
  --cxx-yellow: #f5ce51;
  --cxx-yellow-soft: #fce8a0;
  --cxx-amber: var(--cxx-yellow);
  /* Equipment grades retain their existing five distinct meanings. */
  --cxx-grade-1: #bbc3ca;
  --cxx-grade-2: #7ac995;
  --cxx-grade-3: #65bcec;
  --cxx-grade-4: #c58ae9;
  --cxx-grade-5: #f2bb68;
  --cxx-ally: var(--cxx-cyan);
  --cxx-enemy: var(--cxx-red);
  --cxx-font-ui: "Microsoft YaHei UI","Microsoft YaHei","PingFang SC","Noto Sans CJK SC",system-ui,sans-serif;
  --cxx-font-display: Bahnschrift,"Arial Narrow",var(--cxx-font-ui);
  --cxx-font-mono: Consolas,"Cascadia Mono","SFMono-Regular",monospace;
  /* Existing status-card surfaces retained under explicit roles. */
  --cxx-status-accent-light: #512127;
  --cxx-status-accent-panel: #461c23;
  --cxx-selected-panel: #183b3d;
  --cxx-status-selected-panel: var(--cxx-selected-panel);
  /* Existing commission difficulty cues. */
  --cxx-risk-low: var(--cxx-cyan);
  --cxx-risk-medium: var(--cxx-yellow);
  --cxx-risk-high: var(--cxx-red);
  --cxx-status-card-raised: #291318;
  /* Brother theme roles: concrete values are carried by the document root. */
  --cxx-canvas: var(--cxx-theme-canvas,#100f14);
  --cxx-on-canvas: var(--cxx-theme-on-canvas,#ebe7e5);
  --cxx-on-canvas-muted: var(--cxx-theme-on-canvas-muted,#a59a9c);
  --cxx-line-strong: var(--cxx-theme-line-strong,#f2534c);
  --cxx-heading: var(--cxx-theme-heading,#f2534c);
  --cxx-structure: var(--cxx-theme-structure,#f2534c);
  --cxx-interactive: var(--cxx-theme-interactive,#52e0e8);
  --cxx-on-interactive: var(--cxx-theme-on-interactive,#100f14);
  --cxx-selected: var(--cxx-theme-selected,#4f171b);
  --cxx-on-selected: var(--cxx-theme-on-selected,#ffffff);
  --cxx-attention: var(--cxx-theme-attention,#ffd43f);
  --cxx-on-attention: var(--cxx-theme-on-attention,#100f14);
  --cxx-danger: var(--cxx-theme-danger,#f2534c);
  --cxx-font-latin: var(--cxx-theme-font-latin,Rajdhani,Bahnschrift,var(--cxx-font-ui));
  --cxx-font-label: var(--cxx-theme-font-label,Rajdhani,Bahnschrift,var(--cxx-font-ui));
  --cxx-weight-latin: var(--cxx-theme-weight-latin,600);
  --cxx-weight-heading: var(--cxx-theme-weight-heading,600);
  --cxx-track: var(--cxx-theme-track,.12em);
  --cxx-size-display: var(--cxx-theme-size-display,32px);
  --cxx-size-title: var(--cxx-theme-size-title,30px);
  --cxx-size-display-sm: var(--cxx-theme-size-display-sm,26px);
  --cxx-size-title-sm: var(--cxx-theme-size-title-sm,26px);
  --cxx-preview-red: linear-gradient(90deg,#100f14 0 34%,#f2534c 34% 67%,#52e0e8 67%);
  --cxx-preview-yellow: linear-gradient(90deg,#e9d042 0 34%,#0b0b0b 34% 67%,#00f0ff 67%);
  --cxx-preview-night: linear-gradient(90deg,#0d0f12 0 34%,#eceef1 34% 67%,#e3262e 67%);
  --cxx-cut-s: var(--cxx-theme-cut-s,10px);
  --cxx-cut-m: var(--cxx-theme-cut-m,12px);
  --cxx-cut-l: var(--cxx-theme-cut-l,16px);
}

.cxx-story-library {
  --paper: var(--cxx-ink);
  --line: var(--cxx-line);
  --muted: var(--cxx-muted);
  --red: var(--cxx-red);
  --ice: var(--cxx-cyan);
  position: fixed;
  inset: 3vh 3vw;
  z-index: 2147483002;
  width: 94vw;
  height: 94dvh;
  max-height: 94dvh;
  max-width: 1440px;
  margin: auto;
  background: var(--paper);
  color: var(--cxx-text);
  border: 1px solid var(--cxx-line);
  border-top: 3px solid var(--red);
  box-shadow: 0 24px 100px color-mix(in srgb, var(--cxx-shadow) 80%, transparent);
  font: 16px/1.55 var(--cxx-font-ui);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color-scheme: dark;
  box-sizing: border-box;
}

.cxx-story-library * {
  box-sizing: border-box;
}

.cxx-story-library button {
  font: inherit;
  color: inherit;
  min-height: 44px;
  border: 1px solid var(--line);
  background: var(--cxx-panel);
  padding: 10px 16px;
  cursor: pointer;
  border-radius: 2px;
}

.cxx-story-library input {
  font: inherit;
  color: inherit;
  min-width: 0;
  max-width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  background: var(--cxx-ink);
  border-radius: 2px;
}

.cxx-story-library select {
  font: inherit;
  color: inherit;
  min-width: 0;
  max-width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  background: var(--cxx-ink);
  border-radius: 2px;
}

.cxx-story-library button:hover {
  border-color: var(--ice);
  background: var(--cxx-raised);
}

.cxx-story-library button:disabled {
  opacity: .45;
  cursor: wait;
}

.cxx-story-library :focus-visible {
  outline: 2px solid var(--ice);
  outline-offset: 3px;
}

.cxx-story-library .primary {
  background: var(--cxx-red);
  border-color: var(--red);
  color: var(--cxx-ink);
}

.cxx-story-library .primary:hover {
  background: var(--cxx-red);
}

.cxx-story-library .subtle {
  background: transparent;
}

.cxx-story-library h2 {
  margin: 0;
  font-size: 28px;
  letter-spacing: .06em;
}

.cxx-story-library h3 {
  margin: 0;
  font-size: 20px;
}

.cxx-story-library p {
  margin: 0;
}

.cxx-story-library small {
  color: var(--muted);
  font-size: 13px;
}

.cxx-story-library .muted {
  color: var(--muted);
}

.cxx-story-library .eyebrow {
  color: var(--ice);
  font-size: 13px;
  letter-spacing: .18em;
}

.cxx-story-library .story-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 22px 26px 16px;
  flex: none;
}

.cxx-story-library .story-header p {
  color: var(--muted);
  font-size: 14px;
  margin-top: 4px;
}

.cxx-story-library .story-header>button {
  flex-shrink: 0;
  white-space: nowrap;
}

.cxx-story-library .story-tabs {
  padding: 0 26px;
  display: flex;
  gap: 4px;
  border-bottom: 1px solid var(--line);
  flex: none;
}

.cxx-story-library .story-tabs button {
  padding: 12px 24px;
  border: 0;
  border-bottom: 3px solid transparent;
  background: transparent;
  color: var(--muted);
  border-radius: 0;
}

.cxx-story-library .story-tabs button[aria-selected=true] {
  color: var(--ice);
  border-bottom-color: var(--ice);
  background: var(--cxx-panel);
}

.cxx-story-library .story-workspace {
  display: grid;
  grid-template-columns: minmax(0,1fr) 320px;
  min-height: 0;
  flex: 1;
}

.cxx-story-library .story-main {
  padding: 22px 26px;
  overflow: auto;
  min-height: 0;
}

.cxx-story-library .story-aside {
  padding: 22px;
  background: var(--cxx-panel);
  border-left: 1px solid var(--line);
  overflow: auto;
  min-width: 0;
}

.cxx-story-library .story-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 18px;
}

.cxx-story-library .story-search {
