}

.cxx-story-library button.story-card {
  position: relative;
  padding: 0;
  text-align: left;
  min-width: 0;
  background: var(--cxx-panel);
  border: 1px solid var(--line);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.cxx-story-library button.story-card[aria-pressed=true] {
  border-color: var(--ice);
  box-shadow: 0 0 0 1px var(--ice);
}

.cxx-story-library .story-image {
  aspect-ratio: 16/9;
  position: relative;
  overflow: hidden;
  background: var(--cxx-panel);
  width: 100%;
}

.cxx-story-library .story-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.cxx-story-library .story-image:after {
  content: '';
  position: absolute;
  inset: 45% 0 0;
  background: linear-gradient(transparent,color-mix(in srgb, var(--cxx-ink) 85.1%, transparent));
  pointer-events: none;
}

.cxx-story-library .story-badge {
  position: absolute;
  top: 9px;
  left: 9px;
  z-index: 1;
  padding: 3px 8px;
