  background: color-mix(in srgb, var(--cxx-ink) 87.06%, transparent);
  color: var(--ice);
  border-left: 2px solid var(--ice);
}

.cxx-story-library .story-current {
  color: var(--ice);
  border-color: var(--ice);
}

.cxx-story-library .story-card-copy {
  padding: 12px;
  display: grid;
  gap: 5px;
  min-width: 0;
