  overflow-wrap: anywhere;
}

.cxx-story-library .story-card-copy small {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cxx-story-library .story-card-copy .place {
  color: var(--ice);
}

.cxx-story-library .story-add {
  justify-content: center;
  align-items: center;
  min-height: 210px!important;
  border-style: dashed!important;
