}

.cxx-story-library .story-add span {
  font-size: 34px;
  font-weight: 300;
}

.cxx-story-library .story-pager {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 14px;
  margin-top: 20px;
}

.cxx-story-library .story-aside h3 {
  margin-top: 16px;
  overflow-wrap: anywhere;
}

.cxx-story-library .story-facts {
  display: grid;
  grid-template-columns: 72px minmax(0,1fr);
  gap: 10px;
  margin: 18px 0;
  font-size: 16px;
}

.cxx-story-library .story-facts dt {
  color: var(--muted);
}

.cxx-story-library .story-facts dd {
  margin: 0;
  overflow-wrap: anywhere;
}

.cxx-story-library .story-excerpt {
  border-left: 2px solid var(--cxx-line);
  padding-left: 14px;
  margin: 18px 0;
  color: var(--cxx-text);
  font-size: 16px;
  overflow-wrap: anywhere;
}

.cxx-story-library .story-detail-actions {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 20px;
}

.cxx-story-library .story-info {
  padding: 14px 16px;
  border-left: 2px solid var(--ice);
  background: var(--cxx-panel);
  color: var(--cxx-text);
  margin-bottom: 18px;
  font-size: 16px;
}

.cxx-story-library .story-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px 26px;
  border-top: 1px solid var(--line);
  background: var(--cxx-panel);
  flex: none;
}

.cxx-story-library .story-status {
  color: var(--ice);
  font-size: 14px;
  overflow-wrap: anywhere;
}

.cxx-story-library .story-status.error {
  color: var(--cxx-yellow-soft);
}

.cxx-story-library .story-empty {
