  border: 1px dashed var(--line);
  color: var(--muted);
}

.cxx-story-library .story-empty h3 {
  color: var(--cxx-text);
  margin-bottom: 8px;
}

.cxx-story-library .story-overlay {
  position: absolute;
  inset: 0;
  z-index: 3;
  background: color-mix(in srgb, var(--cxx-ink) 85.1%, transparent);
  display: grid;
  place-items: center;
  padding: 20px;
  overflow: auto;
}

.cxx-story-library .story-modal {
  width: min(650px,100%);
  max-height: 100%;
  overflow: auto;
  padding: 24px;
  background: var(--cxx-panel);
  border: 1px solid var(--cxx-red);
  border-top: 3px solid var(--red);
  box-shadow: 0 20px 80px color-mix(in srgb, var(--cxx-shadow) 73.33%, transparent);
}

.cxx-story-library .story-modal h3 {
  font-size: 24px;
  margin-bottom: 10px;
}

.cxx-story-library .story-modal>p {
  margin: 10px 0 18px;
  color: var(--cxx-text);
}

.cxx-story-library .story-modal label {
  display: grid;
  gap: 6px;
  margin: 16px 0;
  color: var(--cxx-cyan-soft);
}

.cxx-story-library .story-modal .story-image {
  max-height: 230px;
}

.cxx-story-library .story-modal-actions {
  position: sticky;
  bottom: -24px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  flex-wrap: wrap;
  padding: 16px 0 0;
  background: var(--cxx-panel);
  margin-top: 18px;
}

.cxx-story-library .story-modal-actions button {
  min-width: 100px;
}

.cxx-story-library .story-gallery {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 8px;
  margin: 10px 0;
}

