@media (max-width:720px) {
  .cxx-story-library {
    inset: 0;
    width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-left: 0;
    border-right: 0;
  }

  .cxx-story-library h2 {
    font-size: 24px;
  }

  .cxx-story-library .story-header {
    padding: 14px 16px;
  }

  .cxx-story-library .story-header p {
    display: none;
  }

  .cxx-story-library .story-tabs {
    padding: 0 8px;
  }

  .cxx-story-library .story-tabs button {
    flex: 1;
    padding: 11px 8px;
  }

  .cxx-story-library .story-workspace {
    display: block;
    overflow: auto;
  }

  .cxx-story-library .story-main {
    overflow: visible;
    padding: 16px;
  }

  .cxx-story-library .story-aside {
    overflow: visible;
    border-left: 0;
    border-top: 1px solid var(--line);
    padding: 18px 16px;
  }

  .cxx-story-library .story-aside>.story-image {
    max-height: 220px;
  }

  .cxx-story-library .story-grid {
    gap: 10px;
  }

  .cxx-story-library .story-card-copy {
    padding: 10px;
  }

  .cxx-story-library .story-card-copy strong {
    font-size: 16px;
  }

  .cxx-story-library .story-filter {
    max-width: 100%;
    width: 100%;
  }

  .cxx-story-library .story-footer {
    padding: 10px 16px;
    padding-bottom: max(10px,env(safe-area-inset-bottom));
    align-items: flex-start;
  }

  .cxx-story-library .story-footer button {
    padding: 8px 10px;
    flex: none;
  }

  .cxx-story-library .story-overlay {
    padding: 12px;
  }

  .cxx-story-library .story-modal {
    padding: 18px;
  }

  .cxx-story-library .story-modal-actions {
    bottom: -18px;
  }

  .cxx-story-library .story-gallery {
    grid-template-columns: repeat(3,minmax(0,1fr));
  }

  .cxx-story-library .story-add {
    min-height: 180px!important;
  }

  .cxx-story-library .story-search {
    width: 100%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .cxx-story-library * {
    scroll-behavior: auto!important;
  }
}
