.cxx-mailbox {
  position: fixed;
  inset: 0;
  width: min(1080px,94vw);
  height: min(780px,92dvh);
  max-width: 94vw;
  max-height: 92dvh;
  margin: auto;
  padding: 0;
  color: var(--cxx-text);
  background: var(--cxx-ink);
  border: 1px solid var(--cxx-red);
  border-top: 3px solid var(--cxx-red);
  box-shadow: 0 24px 100px color-mix(in srgb, var(--cxx-shadow) 73.33%, transparent);
  font: 16px/1.75 var(--cxx-font-ui);
  overflow: hidden;
  box-sizing: border-box;
  color-scheme: dark;
}

.cxx-mailbox::backdrop {
  background: color-mix(in srgb, var(--cxx-ink) 80%, transparent);
}

.cxx-mailbox * {
  box-sizing: border-box;
}

.cxx-mailbox button {
  min-height: 44px;
  padding: 8px 13px;
  color: var(--cxx-text);
  background: var(--cxx-raised);
  border: 1px solid var(--cxx-line);
  font: inherit;
  cursor: pointer;
  border-radius: 0;
}

.cxx-mailbox button:hover {
  border-color: var(--cxx-red);
}

.cxx-mailbox button:focus-visible {
  outline: 2px solid var(--cxx-cyan);
  outline-offset: -2px;
}

.cxx-mailbox button:disabled {
  opacity: .5;
}

.cxx-mailbox[open] {
  display: flex;
  flex-direction: column;
}

.cxx-mailbox header {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 18px 24px;
  border-bottom: 1px solid var(--cxx-line);
  background: linear-gradient(110deg,var(--cxx-raised),var(--cxx-panel));
}

.cxx-mailbox .mail-brand {
  margin-right: auto;
}

.cxx-mailbox .mail-brand small {
  display: block;
  font: 13px/1.6 var(--cxx-font-mono);
  letter-spacing: .22em;
  color: var(--cxx-cyan);
}

.cxx-mailbox h2 {
  font-size: 26px;
  color: var(--cxx-red);
  margin: 0;
  font-weight: 500;
  letter-spacing: .1em;
}

.cxx-mailbox .mail-layout {
  display: grid;
  grid-template-columns: 310px minmax(0,1fr);
  flex: 1;
  min-height: 0;
}

.cxx-mailbox .mail-list {
  padding: 16px 12px;
  overflow: auto;
  border-right: 1px solid var(--cxx-line);
  scrollbar-width: thin;
}

.cxx-mailbox .mail-list button {
  width: 100%;
  text-align: left;
  display: block;
  margin-bottom: 8px;
  padding: 14px;
  border-color: transparent;
  border-left: 2px solid var(--cxx-line);
  background: var(--cxx-panel);
}

.cxx-mailbox .mail-list button[aria-current=true] {
  background: color-mix(in srgb, var(--cxx-cyan) 12%, transparent);
  border-color: var(--cxx-cyan);
  border-left-color: var(--cxx-cyan);
}

.cxx-mailbox .mail-list button[data-unread=true] {
  border-left-color: var(--cxx-cyan);
}

.cxx-mailbox .mail-list strong {
  display: block;
  font-size: 16px;
  line-height: 1.5;
  font-weight: 500;
  color: var(--cxx-text);
  overflow-wrap: anywhere;
}

.cxx-mailbox .mail-list small {
  display: block;
  color: var(--cxx-muted);
  font-size: 13px;
  margin-top: 7px;
}

.cxx-mailbox article {
  padding: 30px;
  overflow: auto;
  overflow-wrap: anywhere;
  scrollbar-width: thin;
}

.cxx-mailbox article h3 {
  font-size: 24px;
  font-weight: 500;
  line-height: 1.5;
  margin: 12px 0 14px;
  color: var(--cxx-red);
}

.cxx-mailbox article small {
  font-size: 13px;
  color: var(--cxx-cyan);
  display: block;
  border-bottom: 1px solid var(--cxx-line);
  padding-bottom: 18px;
}

.cxx-mailbox .mail-content {
  white-space: pre-wrap;
  font-size: 16px;
  line-height: 1.95;
  margin-top: 24px;
}

.cxx-mailbox .mail-empty {
  display: grid;
  place-items: center;
  text-align: center;
  color: var(--cxx-muted);
  min-height: 240px;
}

.cxx-mailbox footer {
  padding: 10px 22px;
  border-top: 1px solid var(--cxx-line);
  font-size: 13px;
  color: var(--cxx-muted);
  background: var(--cxx-ink);
}

.cxx-mailbox .mail-back {
  display: none;
}

.cxx-mailbox [hidden] {
  display: none!important;
}

@media (max-width:700px) {
  .cxx-mailbox {
    width: 100vw;
    max-width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-left: 0;
    border-right: 0;
  }

  .cxx-mailbox header {
    padding: 12px;
    gap: 7px;
  }

  .cxx-mailbox header button {
    font-size: 16px;
    padding: 8px;
  }

  .cxx-mailbox .mail-brand {
    width: 100%;
  }

  .cxx-mailbox h2 {
    font-size: 23px;
  }

  .cxx-mailbox .mail-layout {
    display: block;
    overflow: auto;
  }

  .cxx-mailbox .mail-list {
    border: 0;
  }

  .cxx-mailbox article {
    padding: 18px;
  }

  .cxx-mailbox article h3 {
    font-size: 22px;
  }

  .cxx-mailbox[data-selected=true] .mail-list {
    display: none;
  }

  .cxx-mailbox[data-selected=false] article {
    display: none;
  }

  .cxx-mailbox .mail-back {
    display: inline-block;
  }

  .cxx-mailbox footer {
    padding: 8px 14px;
  }
}
