:host {
  display: block;
  min-width: 0;
  container: cxx-player / inline-size;
  color: var(--cxx-text);
  font: 16px/1.6 var(--cxx-font-ui);
  color-scheme: dark;
  --cyan: var(--cxx-interactive);
  --muted: var(--cxx-muted);
  --line: var(--cxx-line);
  --yellow: var(--cxx-attention);
