  box-sizing: border-box;
}

*::after {
  box-sizing: border-box;
}

h1 {
  margin: 0;
}

h2 {
  margin: 0;
}

h3 {
  margin: 0;
}

p {
  margin: 0;
}

button {
  font: inherit;
  border-radius: 0;
  cursor: pointer;
  touch-action: manipulation;
  color: inherit;
  background: var(--cxx-raised);
  border: 1px solid var(--cxx-structure);
  min-height: 44px;
  padding: 8px 14px;
}

input {
  font: inherit;
  font-size: 16px;
  border-radius: 0;
  color: var(--cxx-text);
  background: var(--cxx-ink);
  border: 1px solid color-mix(in srgb, var(--cxx-structure) 41.96%, transparent);
  min-height: 44px;
  padding: 8px 12px;
  max-width: 100%;
}

select {
  font: inherit;
  font-size: 16px;
  border-radius: 0;
  color: var(--cxx-text);
  background: var(--cxx-ink);
  border: 1px solid color-mix(in srgb, var(--cxx-structure) 41.96%, transparent);
  min-height: 44px;
  padding: 8px 12px;
  max-width: 100%;
}

button:hover {
  border-color: var(--cyan);
  background: color-mix(in srgb, var(--cxx-interactive) 12%, transparent);
}

button:disabled {
  opacity: .45;
  cursor: default;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

select:focus-visible {
