}

.app {
  position: relative;
  isolation: isolate;
  padding: 18px 26px 24px;
  background: radial-gradient(ellipse at 33% 0,color-mix(in srgb, var(--cxx-structure) 13%, transparent),transparent 56%),linear-gradient(165deg,var(--cxx-panel) 0,var(--cxx-panel) 36%,var(--cxx-ink) 80%);
  height: 100%;
