/* Initial equipment workbench, DESIGN.md 10.12. */
.loadout-setup {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
  color: var(--cxx-text);
  font: 16px/1.6 var(--cxx-font-ui);
}

.loadout-setup>* {
  flex: none;
  margin: 0;
}

.loadout-eyebrow {
  color: var(--cxx-muted);
  font: var(--cxx-weight-latin) 12px/1.3 var(--cxx-font-latin);
  letter-spacing: .14em;
  text-transform: uppercase;
}

.loadout-setup>h3 {
  color: var(--cxx-text);
  font-size: 16px;
  font-weight: 600;
}

.loadout-setup>p:not([class]) {
  color: var(--cxx-muted);
  font-size: 14px;
}

.loadout-list {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 8px;
}

.loadout-list article {
  display: grid;
  min-width: 0;
}

.loadout-setup .loadout-tile {
  position: relative;
  display: grid;
  grid-template-rows: 60px auto auto;
  gap: 4px;
  width: 100%;
  padding: 8px 12px 12px;
  border: 1px solid var(--cxx-line);
  background: color-mix(in srgb, var(--cxx-raised) 55%, transparent);
  text-align: left;
}

.loadout-tile::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 3px;
  background: var(--loadout-grade);
}

.loadout-setup .loadout-tile[aria-pressed=true] {
  border-color: var(--cxx-interactive);
  box-shadow: inset 0 0 0 1px var(--cxx-interactive);
  background: var(--cxx-selected);
  color: var(--cxx-on-selected);
}

[data-cxx-theme=yellow] .loadout-setup .loadout-tile[aria-pressed=true] {
  background: color-mix(in srgb,var(--cxx-interactive) 16%,var(--cxx-panel));
  color: var(--cxx-text);
}

.loadout-asset {
  display: grid;
  place-items: center;
  width: 100%;
  height: 60px;
}

.loadout-asset :is(svg,img) {
  width: 100%;
  height: 60px;
  object-fit: contain;
}

.loadout-list strong {
  color: inherit;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  overflow-wrap: anywhere;
}

.loadout-list :is(p,small) {
  margin: 0;
  color: var(--cxx-muted);
  font-size: 13px;
  line-height: 1.5;
}

.loadout-tile[aria-pressed=true] small {
  color: inherit;
}

.loadout-list>p {
  grid-column: 1/-1;
}

.loadout-setup .loadout-remove {
  margin-top: 4px;
  font-size: 14px;
}

.loadout-setup label {
  display: grid;
  gap: 6px;
  color: var(--cxx-muted);
  font-size: 14px;
}

.loadout-setup :is(input,select,textarea) {
  width: 100%;
  min-height: 44px;
  padding: 8px 12px;
  border: 1px solid var(--cxx-line);
  border-radius: 0;
  background: var(--cxx-canvas);
  color: var(--cxx-text);
  font: inherit;
  font-size: 16px;
}

.loadout-setup textarea {
  min-height: 86px;
  resize: vertical;
}

.loadout-setup :is(input,select,textarea):focus-visible {
  outline: 2px solid var(--cxx-interactive);
  outline-offset: 2px;
}

.loadout-setup button {
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-panel);
  color: var(--cxx-text);
  font: inherit;
  cursor: pointer;
}

@media (hover:hover) and (pointer:fine) {
  .loadout-setup button:hover:enabled {
    border-color: var(--cxx-interactive);
  }
}

.loadout-setup .loadout-form {
  display: grid;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--cxx-line);
  border-top: 2px solid var(--cxx-structure);
  background: color-mix(in srgb, var(--cxx-raised) 60%, transparent);
}

.loadout-form>p {
  padding-left: 12px;
  border-left: 2px solid var(--cxx-line-strong);
  color: var(--cxx-text);
  font-size: 14px;
}

.loadout-form>button {
  justify-self: end;
  min-width: 180px;
  border-color: var(--cxx-interactive);
  background: var(--cxx-interactive);
  color: var(--cxx-on-interactive);
  font-weight: 700;
}

.loadout-setup .loadout-note {
  min-height: 0;
  color: var(--cxx-muted);
  font-size: 13px;
}

.loadout-setup .loadout-note:empty {
  display: none;
}

@supports (corner-shape: bevel) {
  .loadout-setup :is(.loadout-list article,button) {
    border-radius: var(--cxx-cut-s) 0;
    corner-shape: bevel;
  }

  .loadout-setup .loadout-form {
    border-radius: var(--cxx-cut-m) 0;
    corner-shape: bevel;
  }
}

@media (max-width:600px) {
  .loadout-form>button {
    width: 100%;
  }
}

@media (max-width:760px) {
  .loadout-setup .loadout-tile { grid-template-rows:56px auto auto; }
  .loadout-asset,.loadout-asset :is(svg,img) { height:56px; }
}
