  container-type: inline-size;
  background: var(--cxx-panel);
}

.cxx-creator select {
  font: inherit;
  color: inherit;
  color-scheme: dark;
}

.creator-text-field label {
  display: block;
}

.creator-text-field label>span {
  display: block;
  color: var(--coral);
  font-size: 13px;
  margin-bottom: 5px;
}

.creator-gender select {
  display: block;
  width: 100%;
  min-height: 44px;
  background: var(--cxx-canvas);
  border: 1px solid var(--cxx-line);
  padding: 10px 12px;
}

.creator-gender input {
  margin-top: 6px;
}

.cxx-creator .creator-clear-field {
  font-size: 13px;
  min-height: 44px;
  padding: 4px 10px;
  margin-top: 5px;
  background: transparent;
  color: var(--muted);
  border-color: color-mix(in srgb, var(--cxx-line) 33.33%, transparent);
}

.cxx-creator .creator-clear-field[aria-pressed=true] {
  color: var(--cxx-interactive);
}

.cxx-creator select:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

.cxx-creator * {
  box-sizing: border-box;
}

.cxx-creator [hidden] {
  display: none!important;
}

.cxx-creator button {
  font: inherit;
  color: inherit;
  cursor: pointer;
  border: 1px solid var(--edge);
  border-radius: 0;
  background: var(--cxx-panel);
  padding: 7px 13px;
  min-height: 44px;
}

.cxx-creator input {
  font: inherit;
  color: inherit;
}

.cxx-creator textarea {
  font: inherit;
  color: inherit;
}

@media (hover:hover) and (pointer:fine) {
  .cxx-creator button:hover {
    border-color: var(--cxx-interactive);
    color: var(--cxx-text);
  }
}

.cxx-creator :is(button,input,textarea,summary):focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 2px;
}

.creator-heading {
  padding: 18px 24px 8px;
  flex-shrink: 0;
}

.creator-heading small {
