  height: 100%;
  min-height: 0;
  padding: 0!important;
  background: transparent!important;
  overflow: hidden;
}

.app[data-tab=人物]>.eyebrow {
  display: none!important;
}

.app[data-tab=人物]>.title {
  display: none!important;
}

.app[data-tab=人物]>.current-persona {
  display: none!important;
}

.app[data-tab=人物] .layout {
  height: 100%;
  min-height: 0;
  grid-template-rows: minmax(0,1fr)!important;
  gap: 0;
  padding: 0!important;
  border: 0;
}

.app[data-tab=人物] main {
  display: flex;
  flex-direction: column;
  min-height: 0;
  padding: 0!important;
  overflow: hidden;
}

.app[data-tab=人物] .status {
  flex: none;
  font-size: 13px;
  line-height: 20px;
  min-height: 20px;
  margin: 0 0 5px;
  padding: 0;
}

.app[data-tab=人物] .player-view-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.app[data-tab=人物] .player-view-body>.plan {
  flex: none;
  max-height: 30%;
  overflow: auto;
}

.profile-overview {
  flex: 1;
  height: 100%;
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  color: var(--cxx-text);
  font: 16px/1.5 var(--cxx-font-ui);
  --pr: var(--cxx-structure);
  --pc: var(--cxx-interactive);
  --pl: var(--cxx-line);
}

.profile-overview * {
  box-sizing: border-box;
  min-width: 0;
}

.profile-overview [hidden] {
  display: none!important;
}

.profile-overview button {
  font: inherit!important;
  min-height: 44px!important;
  cursor: pointer;
  padding: 8px 12px;
  background: var(--cxx-raised);
  border: 1px solid var(--pl);
  color: var(--cxx-text);
}

.profile-overview button:hover {
  background: color-mix(in srgb, var(--cxx-interactive) 12%, transparent);
  color: var(--cxx-interactive);
  border-color: var(--pc);
}

.profile-overview button:focus-visible {
  outline: 2px solid var(--pc);
  outline-offset: -3px;
}

.profile-overview h2 {
  margin: 0;
}

.profile-overview h3 {
  margin: 0 0 8px;
  color: var(--cxx-heading);
  font: var(--cxx-weight-latin) 13px/1.3 var(--cxx-font-label);
  letter-spacing: var(--cxx-track);
}

/* Section titles read as menu groups (DESIGN.md 10.11). */
.profile-overview h3::before {
  content: "▾ ";
}

.profile-overview p {
  margin: 0;
}

.profile-resource-strip {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr)) auto;
  gap: 20px;
  flex: none;
  padding: 6px 0 12px;
  margin: 0 0 14px;
  border-bottom: 1px solid var(--pl);
}

.profile-resource {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 8px;
  align-items: baseline;
}

.profile-resource span {
  color: var(--cxx-muted);
  font-size: 13px;
}

.profile-resource strong {
  color: var(--cxx-text);
  font: var(--cxx-weight-latin) 24px/1.15 var(--cxx-font-latin);
  white-space: nowrap;
}

.profile-resource progress {
  grid-column: 1/-1;
  width: 100%;
  height: 4px;
  appearance: none;
  border: 0;
  background: var(--cxx-raised);
}

.profile-resource progress::-webkit-progress-bar {
  background: var(--cxx-raised);
}

.profile-resource progress::-webkit-progress-value {
  background: var(--pc);
}

.profile-points {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 13px;
  color: var(--cxx-muted);
  white-space: nowrap;
}

.profile-points b {
  color: var(--cxx-attention);
  margin-left: 6px;
  font: var(--cxx-weight-latin) 20px var(--cxx-font-latin);
}

.profile-columns {
  flex: 1;
  min-height: 0;
  display: grid;
  grid-template-columns: minmax(185px,.9fr) minmax(210px,1.2fr) minmax(245px,1fr);
  grid-template-rows: minmax(0,1fr) auto;
  grid-template-areas: "attributes dossier equipment" "attributes biography equipment";
  gap: 8px 24px;
}

.profile-attributes {
  grid-area: attributes;
  overflow: auto;
  overscroll-behavior: contain;
  padding-right: 8px;
  border-top: 1px solid var(--pl);
  padding-top: 10px;
}

.profile-attribute {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 48px;
  padding: 8px 2px;
  border-bottom: 1px solid color-mix(in srgb, var(--cxx-line) 50%, transparent);
}

.profile-attribute img {
  width: 24px;
  height: 24px;
  object-fit: contain;
  flex: none;
}

.profile-attribute strong {
  font: var(--cxx-weight-latin) 26px/1 var(--cxx-font-latin);
  color: var(--cxx-text);
  margin-left: auto;
}

.profile-attributes>button {
  width: 100%;
  margin-top: 12px;
}

.profile-load {
  margin-top: 12px;
  padding: 10px 12px;
  background: var(--cxx-raised);
  border-left: 2px solid var(--cxx-attention);
  color: var(--cxx-muted);
  font-size: 14px;
}

.profile-load strong {
  color: var(--cxx-attention);
  margin-left: 10px;
  font: var(--cxx-weight-latin) 26px var(--cxx-font-latin);
}

.profile-load p {
  font-size: 16px!important;
  line-height: 1.5;
  margin-top: 6px;
}

.profile-dossier {
  grid-area: dossier;
  min-height: 0;
  display: grid;
  grid-template-rows: minmax(0,1fr) auto auto auto auto;
  justify-items: center;
  text-align: center;
  background: radial-gradient(ellipse at 50% 40%,color-mix(in srgb, var(--cxx-structure) 12%, transparent),transparent 65%);
}

.profile-portrait {
  width: 100%;
  height: 100%;
  min-height: 0;
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 4px 0;
}

.profile-portrait>img {
  width: 100%;
  height: 100%;
  min-height: 0;
  object-fit: contain;
  object-position: center center;
}

.profile-portrait[data-kind=avatar]>img {
  width: min(80%,240px);
  height: 100%;
  object-fit: contain;
}

.profile-seal {
  font-size: 64px;
  font-weight: 500;
  line-height: 1;
  color: var(--cxx-heading);
  padding: 16px;
  border: 1px solid var(--pl);
}

.profile-name {
  font-size: 24px;
  line-height: 1.3;
  font-weight: 500;
  color: var(--cxx-heading);
  overflow-wrap: anywhere;
  max-height: 2.6em;
  overflow: auto;
}

.profile-description {
  font-size: 16px!important;
  line-height: 1.5;
  color: var(--cxx-muted);
  margin: 5px 0 10px!important;
  max-height: 3em;
  overflow: auto;
  overflow-wrap: anywhere;
}

.profile-portrait-caption {
  font: 600 12px/1.4 var(--cxx-font-mono)!important;
  letter-spacing: .1em;
  color: var(--pc);
  margin: 4px 0 8px!important;
  display: none;
}

.profile-change-art {
  width: 100%;
  flex: none;
}

.profile-biography {
  grid-area: biography;
  max-height: 150px;
  overflow: auto;
}

.profile-biography summary {
  min-height: 44px;
  line-height: 24px;
  padding: 10px 0;
  cursor: pointer;
  color: var(--pc);
}

.profile-biography p {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: 16px!important;
  padding: 10px;
  background: var(--cxx-raised);
}

.profile-equipment {
  grid-area: equipment;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border-top: 1px solid var(--pl);
  padding-top: 10px;
}

.profile-equipment h3 {
  flex: none;
}

.profile-equipment-list {
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding-right: 6px;
}

.profile-equipped {
  display: flex!important;
  gap: 12px;
  align-items: center;
  text-align: left;
  width: 100%;
  padding: 8px!important;
  margin-bottom: 6px;
  min-height: 66px!important;
  border-left: 3px solid var(--pc)!important;
  background: color-mix(in srgb, var(--cxx-raised) 55%, transparent)!important;
}

.profile-equipped .profile-item-art {
  width: 64px;
  height: 46px;
  flex: none;
  display: grid;
  place-items: center;
}

.profile-item-art img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}

.profile-item-art svg {
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}

.profile-equipped strong {
  display: block;
  font-size: 16px;
  font-weight: 500;
  overflow-wrap: anywhere;
  line-height: 1.4;
}

.profile-equipped small {
  display: block;
  font-size: 13px;
  color: var(--cxx-muted);
  margin-top: 3px;
}

.profile-equipped[data-weapon=true] strong {
  color: var(--cxx-interactive);
}

.profile-equipment-actions {
  flex: none;
  display: grid;
  gap: 6px;
  padding-top: 10px;
  grid-template-columns: repeat(3,minmax(0,1fr));
}

.profile-combat-summary {
  grid-column: 1/-1;
  max-height: 110px;
  overflow: auto;
  color: var(--pc);
  font-size: 14px;
}

.profile-combat-summary summary {
  min-height: 44px;
  line-height: 24px;
  padding: 10px 0;
  cursor: pointer;
}

.profile-combat-summary p {
  font-size: 16px!important;
  white-space: pre-line;
  color: var(--cxx-muted);
}

.profile-mobile-tabs {
  display: none!important;
}

.inventory-story-portrait {
  max-width: 100%;
  max-height: 480px;
  object-fit: contain;
}

.profile-overview :is(.profile-attributes,.profile-equipment-list,.profile-biography) {
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-structure) transparent;
}

@container cxx-player (max-width:1050px) {
  .profile-points {
    grid-column: 1/-1;
    gap: 18px;
  }

  .profile-resource-strip {
    grid-template-columns: repeat(3,minmax(0,1fr));
    gap: 5px 18px;
    padding-bottom: 8px;
    margin-bottom: 10px;
  }

  .profile-columns {
    gap: 8px 16px;
    grid-template-columns: minmax(165px,.9fr) minmax(180px,1fr) minmax(200px,1fr);
  }

  .profile-equipped .profile-item-art {
    width: 48px;
  }

  .profile-name {
