  z-index: 2;
  isolation: isolate;
}

.node .sprite {
  display: block;
  flex-shrink: 0;
  background-repeat: no-repeat;
  background-size: 2250px 2028px;
  image-rendering: pixelated;
  pointer-events: none;
}

.node[data-state=locked] .sprite {
  filter: brightness(.5);
}

.node:hover {
  filter: brightness(1.45);
}

.node[data-selected=true] {
  outline: 5px solid color-mix(in srgb, var(--cxx-interactive) 65.10%, transparent);
  outline-offset: 9px;
}

.node .rank {
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translate(-50%,15%);
  font: 700 calc(14px / var(--tree-scale, .32))/1 var(--cxx-font-ui);
  padding: 1px 7px;
  background: var(--cxx-ink);
  color: var(--cxx-heading);
  border: 2px solid var(--cxx-line);
}

.node[data-state=available] .rank {
  background: var(--cxx-interactive);
  color: var(--cxx-ink);
  border-color: var(--cxx-interactive);
}

.node[data-state=invested] .rank,
.node[data-state=maxed] .rank {
  background: var(--yellow);
  color: var(--cxx-ink);
  border-color: var(--yellow);
}

.node[data-state=maxed][data-type=milestone]:before,
.node[data-state=maxed][data-type=master]:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%);
  background-size: contain;
  pointer-events: none;
  z-index: -1;
  opacity: .5;
}

.node[data-state=maxed][data-type=milestone]:before {
  background-image: url("cxx-talent-asset:tile-milestone-maxed-glow-f59aa444.png");
}

.node[data-state=maxed][data-type=master]:before {
  background-image: url("cxx-talent-asset:tile-master-maxed-glow-3449f49c.png");
  width: 564px;
  height: 564px;
}

.detail {
  position: absolute;
  right: 22px;
  top: 94px;
  width: 306px;
  max-height: 410px;
  overflow: auto;
  padding: 17px;
  background: linear-gradient(135deg,color-mix(in srgb, var(--cxx-raised) 96.08%, transparent),color-mix(in srgb, var(--cxx-ink) 98.04%, transparent));
  border: 1px solid color-mix(in srgb, var(--cxx-structure) 56.47%, transparent);
  box-shadow: 0 18px 55px color-mix(in srgb, var(--cxx-shadow) 73.33%, transparent);
  z-index: 8;
  font-size: var(--read-size,16px);
  scrollbar-width: thin;
}

.detail[hidden] {
  display: none;
}

.detail h3 {
  font-size: 21px;
  color: var(--cxx-attention);
  margin: 6px 32px 8px 0;
  letter-spacing: .08em;
}

.detail .tag {
  color: var(--cxx-muted);
  font-size: 13px;
  letter-spacing: .05em;
}

.detail .need {
  color: var(--cxx-heading);
  margin: 10px 0;
}

.detail ol {
  padding-left: 23px;
  margin: 0;
  line-height: 1.75;
}

.detail li {
  padding: 5px 0;
  color: var(--cxx-text);
}

.detail li.learned {
  color: var(--cxx-attention);
}

.detail .detail-actions {
  border-top: 1px solid var(--cxx-line);
  margin-top: 12px;
  padding-top: 10px;
  display: flex;
  gap: 8px;
}

.detail .detail-actions button {
  flex: 1;
  min-height: 44px;
}

.detail-close {
  position: absolute;
  right: 9px;
  top: 8px;
  border: 0;
  background: transparent;
  color: var(--cxx-heading);
  font-size: 25px;
  width: 44px;
  height: 44px;
}

.bottom {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 15px 22px;
  border-top: 1px solid color-mix(in srgb, var(--cxx-structure) 23.92%, transparent);
  background: color-mix(in srgb, var(--cxx-panel) 92.94%, transparent);
  flex-wrap: wrap;
}

.draft-state {
  margin-right: auto;
  font-size: 13px;
  color: var(--cxx-muted);
}

.draft-state strong {
  display: block;
  color: var(--cxx-heading);
  font-size: 15px;
}

.hint {
  font-size: var(--read-size,13px);
  color: var(--cxx-muted);
  line-height: 1.6;
  padding: 0 22px 12px;
  background: color-mix(in srgb, var(--cxx-panel) 92.94%, transparent);
}

.notice {
  padding: 0 22px 12px;
  color: var(--cxx-heading);
  background: color-mix(in srgb, var(--cxx-panel) 92.94%, transparent);
  font-size: var(--read-size,13px);
}

.notice:empty {
  display: none;
}

.review,
.records,
.setup {
  font-size: var(--read-size,16px);
  padding: 26px;
  max-width: 850px;
  margin: auto;
  min-height: 450px;
}

.review h3,
.records h3,
.setup h3 {
  font-size: 24px;
  color: var(--cxx-heading);
  letter-spacing: .08em;
  margin-bottom: 16px;
}

.review ul,
.records ol {
  padding-left: 22px;
  line-height: 1.9;
  color: var(--cxx-text);
}

.review p,
.setup p {
  color: var(--cxx-muted);
  margin-bottom: 18px;
}

.review .review-actions {
  display: flex;
  gap: 12px;
  margin-top: 25px;
  flex-wrap: wrap;
}

.records li {
  border-bottom: 1px solid var(--cxx-line);
  padding: 10px 0;
}

.records small {
  display: block;
  color: var(--cxx-muted);
}

.setup-grid {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 12px;
  margin: 20px 0;
}

.setup label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 15px;
  color: var(--cxx-heading);
}

.setup input {
  background: var(--cxx-panel);
  border: 1px solid var(--cxx-line);
  color: var(--cxx-text);
  padding: 8px;
  width: 110px;
  min-width: 0;
}

.setup .setup-values {
  color: var(--cyan);
  line-height: 2;
}

@container (max-width:650px) {
  .bar {
    padding: 15px;
    gap: 12px;
  }

  .brand h2 {
    font-size: 18px;
  }

  .balance {
    gap: 13px;
  }

  .balance strong {
    font-size: 27px;
  }

  .balance p {
    font-size: 13px;
  }

  .bar>.small-button {
    margin-left: auto;
  }

  .overview-viewport {
    height: 520px;
  }

  .workspace {
    min-height: 450px;
  }

  .tree-toolbar {
    padding: 10px;
    gap: 7px;
  }

  .tree-title {
    font-size: 18px;
  }

  .tree-layout {
    grid-template-columns: 46px minmax(0,1fr);
  }

  .tree-nav button {
    height: 59px;
    font-size: 16px;
  }

  .tree-nav img {
    width: 24px;
    height: 24px;
  }

  .tree-scroll {
    min-height: 420px;
    max-height: 520px;
  }

  .detail {
    position: relative;
    inset: auto;
    width: auto;
    max-height: none;
    margin: 10px;
    border-color: color-mix(in srgb, var(--cxx-structure) 50.20%, transparent);
  }

  .bottom {
    padding: 13px;
    gap: 8px;
  }

  .bottom .action {
    flex: 1;
  }

  .draft-state {
    flex-basis: 100%;
  }

  .hint,
  .notice {
    padding-left: 13px;
    padding-right: 13px;
  }

  .review,
  .records,
  .setup {
    padding: 18px;
  }

  .setup-grid {
    grid-template-columns: 1fr;
  }

  .shell {
    min-height: 600px;
  }
}

dialog.detail {
  position: fixed!important;
  inset: auto 12px 12px!important;
  width: calc(100% - 24px)!important;
  max-width: 600px;
  max-height: 70dvh!important;
  margin: 0 auto!important;
  overflow: auto;
  color: var(--cxx-text);
}

dialog.detail::backdrop {
  background: color-mix(in srgb, var(--cxx-ink) 60%, transparent);
}

dialog.detail .detail-close {
  position: sticky;
  top: 0;
  float: right;
  min-width: 44px;
  min-height: 44px;
  background: var(--cxx-raised);
  z-index: 2;
}

dialog.detail .detail-actions {
  position: sticky;
  bottom: -17px;
  background: var(--cxx-panel);
  padding: 12px 0;
}

aside.detail {
  margin: 0;
  right: auto;
  bottom: auto;
  animation: none;
}

.shell {
  min-height: 0;
}

.workspace {
  min-height: 0;
}

.tree-scroll {
  min-height: 230px;
  max-height: 60dvh;
}

.bottom {
  position: relative;
}

@media (prefers-reduced-motion:no-preference) {
  .node,
  .attribute-tile {
    transition: filter .15s;
  }

  .detail {
    animation: cxx-in .15s ease-out;
  }

@keyframes cxx-in {
    from {
      opacity: 0;
      transform: translateY(5px);
    }

    to {
      opacity: 1;
      transform: none;
    }
}
}

