globalThis.CxxOpeningStyle="/* Shared UI roles, emitted into each document and Shadow Root by the card build. */
:root, :host {
  --cxx-ink: var(--cxx-theme-ink,#08080b);
  --cxx-panel: var(--cxx-theme-panel,#120a0d);
  --cxx-raised: var(--cxx-theme-raised,#211217);
  /* Existing opening book/card surfaces share this red tint. */
  --cxx-narrative-panel: #6a1820;
  --cxx-text: var(--cxx-theme-text,#e6e9e8);
  --cxx-muted: var(--cxx-theme-muted,#b5b8bd);
  --cxx-line: var(--cxx-theme-line,#71343f);
  --cxx-shadow: #000;
  /* Shared neutral scrim for modal surfaces. */
  --cxx-scrim: #06080b;
  --cxx-red: #f25964;
  --cxx-red-soft: #ffb5bc;
  --cxx-cyan: #6ecbd0;
  --cxx-cyan-soft: #b9e8eb;
  --cxx-yellow: #f5ce51;
  --cxx-yellow-soft: #fce8a0;
  --cxx-amber: var(--cxx-yellow);
  /* Equipment grades retain their existing five distinct meanings. */
  --cxx-grade-1: #bbc3ca;
  --cxx-grade-2: #7ac995;
  --cxx-grade-3: #65bcec;
  --cxx-grade-4: #c58ae9;
  --cxx-grade-5: #f2bb68;
  --cxx-ally: var(--cxx-cyan);
  --cxx-enemy: var(--cxx-red);
  --cxx-font-ui: "Microsoft YaHei UI","Microsoft YaHei","PingFang SC","Noto Sans CJK SC",system-ui,sans-serif;
  --cxx-font-display: Bahnschrift,"Arial Narrow",var(--cxx-font-ui);
  --cxx-font-mono: Consolas,"Cascadia Mono","SFMono-Regular",monospace;
  /* Existing status-card surfaces retained under explicit roles. */
  --cxx-status-accent-light: #512127;
  --cxx-status-accent-panel: #461c23;
  --cxx-selected-panel: #183b3d;
  --cxx-status-selected-panel: var(--cxx-selected-panel);
  /* Existing commission difficulty cues. */
  --cxx-risk-low: var(--cxx-cyan);
  --cxx-risk-medium: var(--cxx-yellow);
  --cxx-risk-high: var(--cxx-red);
  --cxx-status-card-raised: #291318;
  /* Brother theme roles: concrete values are carried by the document root. */
  --cxx-canvas: var(--cxx-theme-canvas,#100f14);
  --cxx-on-canvas: var(--cxx-theme-on-canvas,#ebe7e5);
  --cxx-on-canvas-muted: var(--cxx-theme-on-canvas-muted,#a59a9c);
  --cxx-line-strong: var(--cxx-theme-line-strong,#f2534c);
  --cxx-heading: var(--cxx-theme-heading,#f2534c);
  --cxx-structure: var(--cxx-theme-structure,#f2534c);
  --cxx-interactive: var(--cxx-theme-interactive,#52e0e8);
  --cxx-on-interactive: var(--cxx-theme-on-interactive,#100f14);
  --cxx-selected: var(--cxx-theme-selected,#4f171b);
  --cxx-on-selected: var(--cxx-theme-on-selected,#ffffff);
  --cxx-attention: var(--cxx-theme-attention,#ffd43f);
  --cxx-on-attention: var(--cxx-theme-on-attention,#100f14);
  --cxx-danger: var(--cxx-theme-danger,#f2534c);
  --cxx-font-latin: var(--cxx-theme-font-latin,Rajdhani,Bahnschrift,var(--cxx-font-ui));
  --cxx-font-label: var(--cxx-theme-font-label,Rajdhani,Bahnschrift,var(--cxx-font-ui));
  --cxx-weight-latin: var(--cxx-theme-weight-latin,600);
  --cxx-weight-heading: var(--cxx-theme-weight-heading,600);
  --cxx-track: var(--cxx-theme-track,.12em);
  --cxx-size-display: var(--cxx-theme-size-display,32px);
  --cxx-size-title: var(--cxx-theme-size-title,30px);
  --cxx-size-display-sm: var(--cxx-theme-size-display-sm,26px);
  --cxx-size-title-sm: var(--cxx-theme-size-title-sm,26px);
  --cxx-preview-red: linear-gradient(90deg,#100f14 0 34%,#f2534c 34% 67%,#52e0e8 67%);
  --cxx-preview-yellow: linear-gradient(90deg,#e9d042 0 34%,#0b0b0b 34% 67%,#00f0ff 67%);
  --cxx-preview-night: linear-gradient(90deg,#0d0f12 0 34%,#eceef1 34% 67%,#e3262e 67%);
  --cxx-cut-s: var(--cxx-theme-cut-s,10px);
  --cxx-cut-m: var(--cxx-theme-cut-m,12px);
  --cxx-cut-l: var(--cxx-theme-cut-l,16px);
}

/* Character creation: the "捏人台" layout (DESIGN.md 10.10).
   Steps on the left, a stage that follows the current choice in the middle, the options panel on the right,
   and the command bar across the foot. Profile and story steps bring their own two-column view,
   so their panel spans the stage. */
.cxx-opening-flow {
  box-sizing: border-box;
  container-type: inline-size;
  container-name: cxx-opening;
  isolation: isolate;
  display: grid;
  grid-template-columns: 232px minmax(0,1fr) 448px;
  grid-template-rows: minmax(0,1fr) auto auto;
  grid-template-areas: "rail stage body" "feedback feedback feedback" "foot foot foot";
  height: 100%;
  min-height: 0;
  overflow: hidden;
  overscroll-behavior: contain;
  color-scheme: dark;
  background: color-mix(in srgb, var(--cxx-canvas) 92%, transparent);
  color: var(--cxx-on-canvas);
  font: 16px/1.6 var(--cxx-font-ui);
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
}

.cxx-opening-flow *,
.cxx-opening-flow *::before,
.cxx-opening-flow *::after {
  box-sizing: border-box;
}

.cxx-opening-flow[hidden],
.cxx-opening-flow [hidden] {
  display: none!important;
}

.cxx-opening-flow button {
  font: inherit;
  cursor: pointer;
}

.cxx-opening-flow button:disabled {
  cursor: default;
  opacity: .5;
}

.cxx-opening-flow :is(button,input,select,textarea,summary):focus-visible {
  outline: 2px solid var(--cxx-interactive);
  outline-offset: 2px;
}

/* The brand line and step counter stay for assistive technology; the rail shows the steps. */
.opening-header {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---------- Step rail ---------- */
.opening-steps {
  grid-area: rail;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 0;
  overflow: auto;
  padding: 20px 0 16px 20px;
  border-right: 1px solid var(--cxx-line);
}

.opening-steps>button {
  flex: none;
  display: grid;
  grid-template-columns: 30px minmax(0,1fr);
  align-items: center;
  min-height: 48px;
  padding: 4px 12px;
  border: 0;
  border-left: 2px solid transparent;
  background: transparent;
  color: var(--cxx-on-canvas-muted);
  text-align: left;
  font-size: 15px;
  transition: background-color .16s,color .16s;
}

.opening-step-num {
  color: inherit;
  font: var(--cxx-weight-latin) 14px/1 var(--cxx-font-latin);
  font-variant-numeric: tabular-nums;
}

.opening-step-value {
  grid-column: 2;
  overflow: hidden;
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
  line-height: 1.4;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.opening-steps>button[data-complete=true] {
  color: var(--cxx-on-canvas);
}

.opening-steps>button[aria-current=step] {
  border-left-color: var(--cxx-structure);
  background: color-mix(in srgb, var(--cxx-structure) 12%, transparent);
  color: var(--cxx-heading);
  font-weight: 600;
}

@media (hover:hover) and (pointer:fine) {
  .opening-steps>button:hover:enabled:not([aria-current=step]) {
    color: var(--cxx-on-canvas);
  }
}

/* ---------- Stage ---------- */
.opening-stage {
  grid-area: stage;
  position: relative;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  border-right: 1px solid var(--cxx-line);
  background: var(--cxx-canvas);
}

.opening-stage::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(0deg,color-mix(in srgb, var(--cxx-canvas) 92%, transparent),transparent 55%);
}

.opening-stage-art {
  position: absolute;
  inset: 0;
}

.opening-stage-art>img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

[data-cxx-theme="yellow"] .opening-stage-art[data-kind=scene]>img {
  /* Scene pictures follow the theme like the game hub (DESIGN.md 10.8). */
  filter: url(#cxx-scene-yellow);
}

[data-cxx-theme="night"] .opening-stage-art[data-kind=scene]>img {
  filter: grayscale(1) brightness(.6);
}

.opening-stage-art>.identity-art-custom {
  position: absolute;
  inset: 0;
}

/* Cyberware icons and the attribute chart sit centred above the caption. */
.opening-stage-art[data-kind=radar] {
  display: grid;
  place-items: center;
  padding: 32px 32px 160px;
}

.opening-forge-bench {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}

.opening-forge-bench::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 52%;
  width: 520px;
  height: 120px;
  transform: translateX(-50%);
  border-radius: 50%;
  background: radial-gradient(ellipse,color-mix(in srgb,var(--loadout-grade) 30%,transparent),transparent 70%);
}

.opening-forge-ring {
  position: absolute;
  left: 50%;
  top: 60%;
  width: 420px;
  height: 70px;
  transform: translateX(-50%);
  border: 1px solid color-mix(in srgb,var(--loadout-grade) 60%,transparent);
  border-radius: 50%;
}

.opening-forge-hero {
  position: relative;
  width: 62%;
  max-width: 480px;
  z-index: 2;
  filter: drop-shadow(0 18px 30px color-mix(in srgb,var(--cxx-shadow) 67%,transparent));
}

.opening-forge-hero img {
  display: block;
  width: 100%;
  height: auto;
}

.opening-forge-stats {
  position: absolute;
  right: 28px;
  top: 24px;
  display: grid;
  gap: 8px;
  width: min(220px,calc(100% - 56px));
  margin: 0;
  z-index: 4;
}

.opening-forge-stats>div {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
}

.opening-forge-stats dd {
  margin: 0;
  color: var(--cxx-on-canvas);
  font: var(--cxx-weight-latin) 15px/1.4 var(--cxx-font-latin);
  font-variant-numeric: tabular-nums;
}

.opening-stage>.cxx-visual-project { z-index:3; }

.opening-radar {
  width: 100%;
  height: 100%;
  max-width: 560px;
}

.opening-radar text {
  fill: var(--cxx-on-canvas-muted);
  font: 13px var(--cxx-font-ui);
}

.opening-radar .opening-radar-value {
  fill: var(--cxx-on-canvas);
  font: var(--cxx-weight-latin) 15px var(--cxx-font-latin);
}

.opening-radar .opening-radar-web {
  fill: none;
  stroke: var(--cxx-line);
}

.opening-radar .opening-radar-anchor {
  fill: none;
  stroke: var(--cxx-on-canvas-muted);
  stroke-dasharray: 4 4;
}

.opening-radar .opening-radar-shape {
  fill: color-mix(in srgb, var(--cxx-structure) 22%, transparent);
  stroke: var(--cxx-structure);
  stroke-width: 2;
}

.opening-stage-caption {
  position: absolute;
  z-index: 1;
  left: 28px;
  right: 28px;
  bottom: 24px;
}

.opening-stage-caption small {
  color: var(--cxx-on-canvas-muted);
  font: var(--cxx-weight-latin) 12px/1.3 var(--cxx-font-latin);
  letter-spacing: .14em;
  text-transform: uppercase;
}

.opening-stage-caption h3 {
  margin: 2px 0 0;
  color: var(--cxx-heading);
  font-size: var(--cxx-size-title);
  line-height: 1.2;
  font-weight: var(--cxx-weight-heading);
}

.opening-stage-caption p {
  max-width: 36em;
  margin: 8px 0 0;
  color: var(--cxx-on-canvas);
  font-size: 15px;
  line-height: 1.7;
}

.opening-stage-scan {
  position: absolute;
  z-index: 2;
  left: 0;
  right: 0;
  top: 0;
  height: 2px;
  background: var(--cxx-structure);
  opacity: 0;
  pointer-events: none;
}

/* ---------- Options panel ---------- */
.cxx-opening-flow .opening-body {
  grid-area: body;
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  padding: 22px 24px;
  background: var(--cxx-panel);
  color: var(--cxx-text);
  scroll-padding: 16px;
}

.cxx-opening-flow .opening-body>* {
  flex: none;
}

.cxx-opening-flow .opening-body h2:focus-visible {
  outline: none;
}

/* Profile, story and draft recovery use their own wide view. */
.cxx-opening-flow:is([data-step=preferences],[data-step=profile],[data-step=scenario],[data-restore=true]) .opening-stage {
  display: none;
}

.cxx-opening-flow:is([data-step=preferences],[data-step=profile],[data-step=scenario],[data-restore=true]) .opening-body {
  grid-column: stage-start / body-end;
}

.cxx-opening-flow[data-step=profile] .opening-body {
  padding: 0;
  overflow: hidden;
}

.cxx-opening-flow[data-step=scenario] .opening-body {
  padding: 16px 24px;
}

/* The selected origin's description is read aloud; the stage shows it on screen. */
.opening-origin-description {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

/* ---------- Command bar ---------- */
.opening-footer {
  grid-area: foot;
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 64px;
  padding: 8px 24px;
  border-top: 1px solid var(--cxx-line);
  background: var(--cxx-canvas);
}

.opening-key {
  display: none;
  align-items: center;
  gap: 8px;
  color: var(--cxx-on-canvas-muted);
  font-size: 14px;
  white-space: nowrap;
}

.cxx-game-menu .opening-key {
  display: inline-flex;
}

.opening-kbd {
  display: inline-grid;
  place-items: center;
  min-width: 28px;
  height: 24px;
  padding: 0 6px;
  border: 1px solid currentColor;
  font: var(--cxx-weight-latin) 13px/1 var(--cxx-font-latin);
}

.opening-footnote {
  margin-right: auto;
  color: var(--cxx-on-canvas-muted);
  font-size: 14px;
}

.cxx-opening-flow :is(.opening-back,.opening-next) {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-panel);
  color: var(--cxx-text);
  white-space: nowrap;
  transition: background-color .16s,border-color .16s,filter .16s;
}

.cxx-opening-flow .opening-next {
  border-color: var(--cxx-interactive);
  background: var(--cxx-interactive);
  color: var(--cxx-on-interactive);
  font-weight: 700;
}

@media (hover:hover) and (pointer:fine) {
  .cxx-opening-flow .opening-back:hover:enabled {
    border-color: var(--cxx-interactive);
  }

