.cxx-opening-flow .opening-band-hero {
  position: absolute;
  right: -4%;
  bottom: -30%;
  height: 130%;
  width: auto;
  max-width: 75%;
  object-fit: contain;
  object-position: right bottom;
}

.cxx-opening-flow .opening-band-card::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg,color-mix(in srgb, var(--cxx-canvas) 92%, transparent),transparent 60%);
}

.cxx-opening-flow .opening-band-copy {
