body {
  font-family: var(--cxx-font-ui);
}

@keyframes uika-fade {
  from {
    opacity: 0;
    transform: translateY(15px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.uika-wrap {
  position: relative;
  max-width: 760px;
  margin: 20px auto;
  animation: uika-fade 1s ease-out;
  --cp-ink: var(--cxx-ink);
  --cp-panel: var(--cxx-panel);
  --cp-panel-hi: var(--cxx-raised);
  --cp-line: var(--cxx-line);
  --cp-cyan: var(--cxx-cyan);
  --cp-red: var(--cxx-red);
  --cp-amber: var(--cxx-yellow);
  --cp-text: var(--cxx-text);
  --cp-muted: var(--cxx-muted);
  font-family: var(--cxx-font-ui);
  color: var(--cp-text);
}

.uika-book {
  position: relative;
  display: flex;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% -18%,color-mix(in srgb, var(--cxx-narrative-panel) 50%, transparent),transparent 62%),repeating-linear-gradient(0deg,transparent 0 31px,color-mix(in srgb, var(--cxx-red) 2.20%, transparent) 31px 32px),var(--cp-ink);
  border: 1px solid var(--cp-line);
  border-radius: 2px;
  box-shadow: 0 18px 46px color-mix(in srgb, var(--cxx-shadow) 42%, transparent),inset 0 1px color-mix(in srgb, var(--cxx-red) 18.00%, transparent);
}

.uika-spine {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  width: 40px;
  transform: translateX(-50%);
  z-index: 10;
  pointer-events: none;
  background: linear-gradient(90deg,transparent,color-mix(in srgb, var(--cxx-red) 35.00%, transparent),transparent);
  box-shadow: none;
}

.uika-holes {
  position: absolute;
  left: 50%;
  top: 0;
  bottom: 0;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  justify-content: space-evenly;
  padding: 20px 0;
}

.uika-hole {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: var(--cp-ink);
  box-shadow: inset 2px 2px 4px color-mix(in srgb, var(--cxx-shadow) 80%, transparent),0 0 0 1px var(--cp-line);
}

.uika-page-left {
  flex: 1;
  padding: 40px;
  position: relative;
  background: transparent;
}

.uika-photo-frame {
  padding: 12px 12px 45px 12px;
  transform: rotate(-2deg);
  transition: transform 0.3s ease;
  margin-top: 10px;
  background: var(--cp-panel-hi);
  border: 1px solid var(--cp-line);
  border-radius: 2px;
  box-shadow: 0 8px 20px color-mix(in srgb, var(--cxx-shadow) 35%, transparent);
  padding-bottom: 38px;
}

.uika-photo-frame:hover {
  transform: rotate(0deg) scale(1.02);
  box-shadow: 4px 8px 20px color-mix(in srgb, var(--cxx-shadow) 12%, transparent), 0 0 0 1px var(--cxx-shadow);
}

.uika-img {
  display: block;
  border: 1px solid var(--cxx-line);
  height: 340px;
  width: 100%;
  object-fit: cover;
  object-position: top;
  filter: saturate(.78) contrast(1.05);
  border-radius: 1px;
}

.uika-photo-text {
  position: absolute;
  left: 0;
  right: 0;
  text-align: center;
  font-style: italic;
  font-size: 14px;
  letter-spacing: 1px;
  color: var(--cp-cyan);
  bottom: 10px;
  font-family: var(--cxx-font-mono);
}

.uika-star {
  position: absolute;
  top: 20px;
  left: 30px;
  font-size: 24px;
  opacity: 0.6;
  color: var(--cp-amber);
}

.uika-page-right {
  flex: 1;
  padding: 40px 40px 40px 50px;
  position: relative;
  display: flex;
  flex-direction: column;
  background: transparent;
}

.uika-date {
  font-size: 18px;
  margin-bottom: 20px;
  padding-bottom: 10px;
  letter-spacing: 1px;
  color: var(--cp-amber);
  border-bottom: 1px dashed var(--cp-line);
  font-family: var(--cxx-font-mono);
  font-style: normal;
}

.uika-gif-box {
  align-self: flex-start;
  margin-bottom: 24px;
  overflow: hidden;
  border: 1px solid var(--cp-line);
  border-radius: 2px;
  background: var(--cp-panel-hi);
  box-shadow: none;
}

.uika-gif {
  height: 90px;
  width: auto;
  display: block;
  filter: saturate(.78) contrast(1.05);
  border-radius: 1px;
}

.uika-text {
  font-size: 14px;
  line-height: 2;
  margin-bottom: 30px;
  text-align: justify;
  color: var(--cp-text);
}

.uika-text p {
  margin: 0 0 12px 0;
}

.uika-btn-wrap {
  margin-top: auto;
  text-align: center;
}

.uika-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 14px 36px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 4px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25,0.8,0.25,1);
  user-select: none;
  text-decoration: none;
  color: var(--cp-ink);
  background: var(--cp-cyan);
  border: 1px solid var(--cp-cyan);
  border-radius: 2px;
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--cxx-cyan) 22.00%, transparent);
  text-shadow: none;
}

.uika-btn:hover {
  transform: translateY(-3px);
  background: var(--cxx-cyan);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--cxx-cyan) 12.00%, transparent),0 6px 20px color-mix(in srgb, var(--cxx-cyan) 15.00%, transparent);
  color: var(--cp-ink);
}

.uika-btn:active {
  transform: translateY(1px);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--cxx-yellow) 20.00%, transparent);
}

.uika-btn-icon {
  font-size: 18px;
}

.uika-ending {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.8s ease;
  background: color-mix(in srgb, var(--cxx-ink) 93%, transparent);
  backdrop-filter: blur(3px);
}

.uika-ending.act {
  opacity: 1;
  pointer-events: auto;
}

.uika-end-text {
  font-size: 22px;
  letter-spacing: 6px;
  font-weight: bold;
  transform: translateY(10px);
  transition: transform 0.8s ease;
  color: var(--cp-cyan);
  text-shadow: none;
}

.uika-ending.act .uika-end-text {
  transform: translateY(0);
}

@media (max-width:650px) {
  .uika-book {
    flex-direction: column;
  }

  .uika-spine {
    left: 0;
    top: 50%;
    bottom: auto;
    right: 0;
    height: 30px;
    width: 100%;
    transform: translateY(-50%);
    background: linear-gradient(180deg, color-mix(in srgb, var(--cxx-yellow-soft) 10.00%, transparent), color-mix(in srgb, var(--cxx-yellow) 40.00%, transparent), color-mix(in srgb, var(--cxx-yellow-soft) 10.00%, transparent));
  }

  .uika-holes {
    flex-direction: row;
    width: 100%;
    height: auto;
    padding: 0 20px;
  }

  .uika-page-left {
    padding: 30px 25px 25px 25px;
  }

  .uika-page-right {
    padding: 25px 25px 30px 25px;
  }
}

