  color: var(--cp-ink);
}

.taki-btn:active {
  transform: translate(0, 0);
  box-shadow: 0 0 0 transparent;
}

.taki-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
  background: color-mix(in srgb, var(--cxx-ink) 93%, transparent);
