  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, color-mix(in srgb, var(--cxx-raised) 8%, transparent), transparent);
  transition: left 0.5s ease;
}

.mutsumi-btn:hover::before {
  left: 100%;
}

.mutsumi-btn:hover {
  transform: translateY(-2px);
  background: var(--cxx-cyan);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--cxx-cyan) 12.00%, transparent),0 6px 20px color-mix(in srgb, var(--cxx-cyan) 15.00%, transparent);
  color: var(--cp-ink);
}

.mutsumi-btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 8px color-mix(in srgb, var(--cxx-cyan) 15%, transparent);
}

.mutsumi-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 15px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.6s ease;
  overflow: hidden;
  background: transparent;
}

.mutsumi-page-turn {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  transform: translateX(100%);
  transition: transform 0.7s cubic-bezier(0.4, 0, 0.2, 1);
  z-index: 1;
  background: linear-gradient(135deg,var(--cxx-ink),var(--cxx-ink));
}

.mutsumi-overlay.active .mutsumi-page-turn {
  transform: translateX(0);
}

.mutsumi-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.mutsumi-over-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
