body {
  font-family: var(--cxx-font-ui);
}

@keyframes soyo-pop {
  0% {
    opacity: 0;
    transform: scale(0.92) translateY(15px);
  }

  60% {
    transform: scale(1.01) translateY(-2px);
  }

  100% {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

@keyframes soyo-sparkle {
  0%, 100% {
    opacity: 0.3;
    transform: scale(0.8) rotate(0deg);
  }

  50% {
    opacity: 1;
    transform: scale(1.2) rotate(15deg);
  }
}

@keyframes soyo-float {
  0%, 100% {
    transform: translateY(0px) rotate(0deg);
  }

  50% {
    transform: translateY(-5px) rotate(2deg);
  }
}

@keyframes soyo-wave {
  0%, 100% {
    transform: translateX(0);
  }

  50% {
    transform: translateX(3px);
  }
}

@keyframes soyo-heartbeat {
  0%, 100% {
    transform: scale(1);
  }

  50% {
    transform: scale(1.15);
  }
}

.soyo-wrap {
  max-width: 780px;
  margin: 30px auto;
  animation: soyo-pop 0.8s cubic-bezier(0.2, 0.8, 0.2, 1);
  position: relative;
  --cp-ink: var(--cxx-ink);
  --cp-panel: var(--cxx-panel);
  --cp-panel-hi: var(--cxx-raised);
  --cp-line: var(--cxx-line);
  --cp-cyan: var(--cxx-cyan);
  --cp-red: var(--cxx-red);
  --cp-amber: var(--cxx-yellow);
  --cp-text: var(--cxx-text);
  --cp-muted: var(--cxx-muted);
  font-family: var(--cxx-font-ui);
  color: var(--cp-text);
}

.soyo-journal {
