  background: radial-gradient(ellipse at 50% -18%,color-mix(in srgb, var(--cxx-narrative-panel) 50%, transparent),transparent 62%),repeating-linear-gradient(0deg,transparent 0 31px,color-mix(in srgb, var(--cxx-red) 2.20%, transparent) 31px 32px),var(--cp-ink);
  border: 1px solid var(--cp-line);
  border-radius: 2px;
  box-shadow: 0 18px 46px color-mix(in srgb, var(--cxx-shadow) 42%, transparent);
}

.soyo-tape-top {
  position: absolute;
  top: -6px;
  left: 40px;
  width: 80px;
  height: 24px;
  transform: rotate(-2deg);
  z-index: 15;
  background: repeating-linear-gradient(45deg,color-mix(in srgb, var(--cxx-yellow) 50.00%, transparent),color-mix(in srgb, var(--cxx-yellow) 50.00%, transparent) 4px,color-mix(in srgb, var(--cxx-yellow) 25.00%, transparent) 4px,color-mix(in srgb, var(--cxx-yellow) 25.00%, transparent) 8px);
  border-radius: 0 0 2px 2px;
  box-shadow: none;
}

.soyo-tape-top2 {
  position: absolute;
  top: -4px;
  right: 60px;
  width: 65px;
  transform: rotate(3deg);
  z-index: 15;
  background: var(--cp-red);
  height: 2px;
  border-radius: 0;
  box-shadow: none;
}

.soyo-inner {
  display: flex;
  gap: 0;
  padding: 35px 30px 30px 30px;
  position: relative;
  background: transparent;
}

.soyo-left {
  flex: 1.1;
  padding: 15px 25px 15px 15px;
  display: flex;
  flex-direction: column;
  position: relative;
  z-index: 2;
  background: transparent;
}

.soyo-date-sticker {
  align-self: flex-start;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 16px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  margin-bottom: 18px;
  box-shadow: 0 3px 8px color-mix(in srgb, var(--cxx-yellow-soft) 30.00%, transparent);
  position: relative;
  background: color-mix(in srgb, var(--cxx-yellow) 8.00%, transparent);
  border: 1px dashed color-mix(in srgb, var(--cxx-yellow) 45.00%, transparent);
  color: var(--cp-amber);
  border-radius: 2px;
}

.soyo-date-sticker::after {
  content: '☀';
  font-size: 14px;
}

.soyo-name {
  font-family: var(--cxx-font-ui);
  font-size: 34px;
  font-weight: 700;
  margin: 0 0 2px 0;
  letter-spacing: 2px;
  color: var(--cp-red);
}

.soyo-name-jp {
  font-size: 15px;
  font-weight: 500;
  margin-bottom: 22px;
  letter-spacing: 4px;
  color: var(--cp-muted);
}

.soyo-text-area {
  padding: 8px 5px;
  margin-bottom: 20px;
  background: color-mix(in srgb, var(--cxx-ink) 75%, transparent);
  border: 1px solid var(--cp-line);
  border-radius: 2px;
}

.soyo-text {
  font-size: 14px;
  line-height: 30px;
  text-align: justify;
  color: var(--cp-text);
}

.soyo-text p {
  margin: 0;
}

.soyo-memo {
  align-self: flex-start;
  position: relative;
  padding: 8px 8px 25px 8px;
  box-shadow: 2px 3px 8px color-mix(in srgb, var(--cxx-shadow) 6%, transparent),
        0 0 0 1px color-mix(in srgb, var(--cxx-yellow-soft) 20.00%, transparent);
  transform: rotate(-1.5deg);
  transition: transform 0.3s ease;
  margin-top: auto;
  background: color-mix(in srgb, var(--cxx-cyan) 5.00%, transparent);
  border-left: 2px solid var(--cp-cyan);
  border-radius: 0 2px 2px 0;
}

.soyo-memo:hover {
  transform: rotate(0deg) scale(1.03);
}

.soyo-gif {
  height: 88px;
  width: auto;
  display: block;
  filter: saturate(.78) contrast(1.05);
  border-radius: 1px;
}

.soyo-memo-label {
  position: absolute;
  bottom: 5px;
  right: 8px;
  font-family: var(--cxx-font-ui);
  font-size: 13px;
  color: var(--cp-cyan);
}

.soyo-memo::after {
  content: '';
  position: absolute;
  bottom: 0;
  right: 0;
  width: 18px;
  height: 18px;
  background: linear-gradient(135deg, var(--cxx-yellow-soft) 45%, var(--cxx-yellow) 50%, var(--cxx-yellow) 100%);
  box-shadow: -1px -1px 2px color-mix(in srgb, var(--cxx-shadow) 3%, transparent);
}

.soyo-divider {
  width: 35px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-shrink: 0;
  padding: 20px 0;
}

.soyo-flower {
  width: 14px;
  height: 14px;
  position: relative;
  color: var(--cp-red);
}

.soyo-flower::before {
  content: '';
