  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--cxx-yellow-soft);
  border-radius: 50%;
  box-shadow: 0 -8px 0 -2px var(--cxx-yellow-soft),
        0 8px 0 -2px var(--cxx-yellow-soft),
        -8px 0 0 -2px var(--cxx-yellow-soft),
        8px 0 0 -2px var(--cxx-yellow-soft),
        -5px -5px 0 -2px var(--cxx-yellow-soft),
        5px -5px 0 -2px var(--cxx-yellow-soft),
        -5px 5px 0 -2px var(--cxx-yellow-soft),
        5px 5px 0 -2px var(--cxx-yellow-soft);
}

.soyo-flower::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  right: 3px;
  bottom: 3px;
  background: var(--cxx-yellow-soft);
  border-radius: 50%;
}

.soyo-dash-line {
  width: 1px;
  flex: 1;
  background: repeating-linear-gradient(
        180deg,
        color-mix(in srgb, var(--cxx-yellow-soft) 40.00%, transparent) 0px,
        color-mix(in srgb, var(--cxx-yellow-soft) 40.00%, transparent) 5px,
