  z-index: 2;
  background: transparent;
}

.soyo-portrait-card {
  position: relative;
  padding: 10px;
  transition: all 0.3s ease;
  max-width: 260px;
  background: var(--cp-panel-hi);
  border: 1px solid var(--cp-line);
  border-radius: 2px;
  box-shadow: 0 8px 20px color-mix(in srgb, var(--cxx-shadow) 35%, transparent);
}

.soyo-portrait-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 12px 28px color-mix(in srgb, var(--cxx-yellow-soft) 25.00%, transparent);
}

.soyo-portrait {
  display: block;
  height: 360px;
  width: 100%;
  object-fit: cover;
  object-position: top;
  filter: saturate(.78) contrast(1.05);
  border-radius: 1px;
}

.soyo-photo-tape {
  position: absolute;
  top: -8px;
  left: 30px;
  width: 55px;
  transform: rotate(-5deg);
  z-index: 5;
  background: var(--cp-cyan);
  height: 2px;
  border: none;
  box-shadow: none;
  border-radius: 0;
}

.soyo-photo-tape2 {
  position: absolute;
  bottom: -6px;
  right: 25px;
  width: 50px;
  transform: rotate(3deg);
  z-index: 5;
  background: var(--cp-red);
  height: 2px;
  border: none;
  box-shadow: none;
  border-radius: 0;
}

.soyo-photo-caption {
  font-family: var(--cxx-font-ui);
  text-align: center;
  margin-top: 12px;
  font-size: 16px;
  letter-spacing: 1px;
  color: var(--cp-cyan);
}

.soyo-deco-star {
  position: absolute;
  font-size: 16px;
  opacity: 0.5;
  animation: soyo-sparkle 3s ease-in-out infinite;
  z-index: 1;
  pointer-events: none;
  color: var(--cp-amber);
}

.soyo-deco-star:nth-child(1) {
  top: 25px;
  right: 30px;
  font-size: 14px;
  animation-delay: 0s;
}

.soyo-deco-star:nth-child(2) {
  bottom: 80px;
  left: 20px;
  font-size: 18px;
  animation-delay: 1s;
}

.soyo-deco-star:nth-child(3) {
  top: 60px;
  left: 50%;
  font-size: 12px;
  animation-delay: 0.5s;
}

.soyo-deco-star:nth-child(4) {
  bottom: 30px;
  right: 80px;
  font-size: 15px;
  animation-delay: 1.5s;
}

.soyo-deco-star:nth-child(5) {
  top: 45%;
  right: 15px;
  font-size: 10px;
  animation-delay: 2s;
}

.soyo-deco-heart {
  position: absolute;
  z-index: 1;
  pointer-events: none;
  opacity: 0.3;
  animation: soyo-heartbeat 2.5s ease-in-out infinite;
  color: var(--cp-red);
}

.soyo-deco-heart::before {
  content: '♥';
  color: var(--cxx-red-soft);
  font-size: 14px;
}

.soyo-deco-heart:nth-of-type(1) {
  bottom: 50px;
  left: 50%;
  animation-delay: 0.5s;
}

.soyo-deco-heart:nth-of-type(2) {
  top: 35px;
  left: 45%;
  animation-delay: 1.2s;
}

