  pointer-events: none;
  display: flex;
  gap: 3px;
}

.soyo-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  opacity: 0.5;
  background: var(--cp-line);
}

.soyo-dot:nth-child(2) {
  background: var(--cxx-red-soft);
  width: 3px;
  height: 3px;
}

.soyo-dot:nth-child(3) {
  background: var(--cxx-cyan-soft);
  width: 5px;
  height: 5px;
}

.soyo-action {
  text-align: center;
  padding: 0 30px 28px 30px;
