.soyo-btn-icon {
  font-size: 16px;
  animation: soyo-wave 1.5s ease-in-out infinite;
}

.soyo-overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 30;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s ease;
  border-radius: 20px;
  background: color-mix(in srgb, var(--cxx-ink) 93%, transparent);
  backdrop-filter: blur(3px);
}

.soyo-overlay.active {
  opacity: 1;
  pointer-events: auto;
}

.soyo-loader {
  display: flex;
  gap: 8px;
}

.soyo-loader-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  animation: soyo-bounce 1.2s ease-in-out infinite;
  background: var(--cp-red);
}

.soyo-loader-dot:nth-child(2) {
  animation-delay: 0.15s;
  background: var(--cxx-red-soft);
}

.soyo-loader-dot:nth-child(3) {
  animation-delay: 0.3s;
  background: var(--cxx-cyan-soft);
}

@keyframes soyo-bounce {
  0%, 80%, 100% {
    transform: translateY(0);
  }

  40% {
    transform: translateY(-12px);
  }
}

.soyo-over-txt {
  font-family: var(--cxx-font-ui);
  font-size: 22px;
  letter-spacing: 4px;
  color: var(--cp-cyan);
  text-shadow: none;
}

.soyo-wave-bottom {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 30px;
