.soyo-wave-bottom::before {
  content: '';
  position: absolute;
  bottom: 0;
  left: -10%;
  right: -10%;
  height: 50px;
  background: color-mix(in srgb, var(--cxx-yellow-soft) 6.00%, transparent);
  border-radius: 50% 50% 0 0;
