@media (max-width: 680px) {
  .soyo-inner {
    flex-direction: column;
    padding: 30px 20px 20px 20px;
  }

  .soyo-divider {
    width: 100%;
    height: 30px;
    flex-direction: row;
    padding: 0 20px;
  }

  .soyo-dash-line {
    width: auto;
    height: 1px;
