  .soyo-left {
    padding: 10px 5px;
  }

  .soyo-right {
    padding: 10px 5px;
  }

  .soyo-portrait-card {
    max-width: 200px;
  }

  .soyo-action {
    padding: 0 20px 25px;
  }
