 const mapTool=CxxAtlasToolFactory.create({window:parent,api:globalThis,runtime,maps,content:CxxContent,base:{"quests":[{"id":"q01","title":"巴的采购单","fixer":"秤叔","fixerNote":"红花街·旧当铺「公平秤」的柜台后头","district":"红花街","type":"回收","difficulty":"低","pay":30000,"payNote":"","deadline":"无","brief":"巴的诊所你总该听过——收费实在，手艺好，能扛事。她订了批皮下护甲，卖家临时放了鸽子，货现在蹲在清道夫的抛货点里落灰。你去把它端回来，巴付账，我抽一成。别问货是哪来的，你也没看见，对吧。","goal":"到抛货点清点并取回整批皮下护甲（六套），送到巴的诊所后账。","terms":"护甲别磕碰；巴只认完好件。","risk":"抛货点常有清道夫的人回头翻检——撞上了别硬碰，你是他们清单上没有的人。","bonus":"无损交付：六套护甲完好无损，加成 10%。","unlock":"无","flagship":false,"mapId":"tokyo-central","placeId":"a-yang-clinic"},{"id":"q02","title":"被盯上的壳","fixer":"秤叔","fixerNote":"红花街·旧当铺「公平秤」的柜台后头","district":"红花街","type":"救人","difficulty":"中","pay":80000,"payNote":"","deadline":"两日内","brief":"有个机偶姑娘在红花街西口被人盯上了——清道夫那帮摘器官的把她当成行走的备件库。她弟弟在我的柜台上押了最后一枚旧币换消息，我收下了，也打算把事情办了。把人带去巴的诊所，别让她变成夜市摊上的零件。","goal":"找到她（西口夜市一带），把她完整地送到巴的诊所。","terms":"她是非法机偶，警视厅不管——也别让警视厅看见；她自己可能不配合，多点耐心。","risk":"清道夫双人组轮流盯梢；红花街夜里不好走。","bonus":"不惊动：全程避开清道夫眼线，加成 30%。","unlock":"无","flagship":false,"mapId":"tokyo-central","placeId":"a-yang-clinic"},{"id":"q03","title":"把吉他送过铁丝网","fixer":"玲姐","fixerNote":"RiNG 社区·场务棚，嗓门比灯还亮","district":"RiNG 社区","type":"护送","difficulty":"低","pay":25000,"payNote":"","deadline":"明晚演出前","brief":"河沿那边有支小乐队租了排练房，一把旧世代的贝斯还押在我们仓库。明晚他们要用——但这把琴比在场一半人的年纪都大，磕一下就是事故。你腿脚利索，帮我把它从 RING-Live! 后门送到荒川河沿。都是街坊的事，别让我失望。","goal":"明晚八点前，把贝斯完好送到荒川河沿的排练房，拿回签收条。","terms":"琴不许离手；路上有人借看，一律摇头。","risk":"河沿带夜里治安差，抢器材的和收过路费的都不新鲜。","bonus":"零损伤：琴身无一道新伤，加成 20%。","unlock":"无","flagship":false,"mapId":"tokyo-central","placeId":"ring-live"},{"id":"q04","title":"谁在偷我们的电","fixer":"玲姐","fixerNote":"RiNG 社区·场务棚，嗓门比灯还亮","district":"RiNG 社区","type":"渗透调查","difficulty":"中","pay":60000,"payNote":"","deadline":"无","brief":"RiNG 社区这礼拜跳了三次闸，全楼道的义眼都得重启。电是我管的，账是我平的，跳下去我先倒霉。社区管道图上多出一条不存在的支线——顺着它查，看看是哪路神仙在偷电。查清楚了就行，怎么处理等我发话。","goal":"查明偷电支线的源头与用途，回报玲姐。","terms":"只查不动手；别打草惊蛇，也别把自己搭进去。","risk":"支线那头通向地下室—— RiNG 的地下室不全是空着的。","bonus":"人赃并获：拍到可指认的画面而非只剪了线，加成 25%。","unlock":"无","flagship":false,"mapId":"tokyo-central","placeId":"ring-community"},{"id":"q05","title":"三楼的空办公室","fixer":"教授","fixerNote":"新日本时代广场·二手芯片铺「百科全数」的店主","district":"新日本时代广场","type":"渗透调查","difficulty":"中","pay":90000,"payNote":"","deadline":"无","brief":"中小公司大厦，东翼三楼，挂牌的是家做翻译软件的小公司——工资照发、工位照摆，三个月没人上班。整栋楼的电力曲线却夜里陡增。信息含量，值得你冒这个险。进去看看，拍点东西回来。","goal":"潜入三楼，查明夜间真实活动并取证回报。","terms":"见好就收；你的任务是把信息带回来，不是把门拆下来。","risk":"大楼有外包安保，巡逻表是死的，人是活的。","bonus":"不惊动：未触发任何警报与上报，加成 30%。","unlock":"无","flagship":false},{"id":"q06","title":"被雪藏的试音带","fixer":"教授","fixerNote":"新日本时代广场·二手芯片铺「百科全数」的店主","district":"弦卷集团子公司","type":"偷窃","difficulty":"高","pay":150000,"payNote":"","deadline":"无","brief":"有个嗓子很好的姑娘，两年前签给弦卷旗下的厂牌，试音带录完就被公司压进档案库——理由是「定位不符」。她付不起违约金，只付得起我这单的钱。去档案库，把那份试音带的数据拷出来。这不算偷，这是把人家自己的嗓子还给人家。","goal":"进入子公司档案库，拷出指定试音带数据，原样带回。","terms":"只拷指定文件；库里的别的东西看都别多看一眼。","risk":"企业档案库有智能哨戒与审计日志，痕迹就是罪证。","bonus":"不留痕：日志零异常，加成 40%。","unlock":"无","flagship":false},{"id":"q07","title":"夜半歌声","fixer":"老龟","fixerNote":"平民区·修车行「龟尾」，永远在车底下","district":"平民区","type":"清除","difficulty":"高","pay":120000,"payNote":"","deadline":"无","brief":"我这条街上有间黑超梦作坊，夜夜放素材，声音顺着下水道飘上来——听过的老人现在不敢睡觉，有个孩子至今在做噩梦。作坊背后是谁我不问，我只问街道安宁。把播放点端了。手脚干净点，别在我地盘上放火。","goal":"找到作坊播放点并将其瘫痪，令其无法继续营业。","terms":"不得伤及被扣押的素材演员；不得波及邻栋。","risk":"作坊有常驻看场，背后金主身份不明——惹不起就撤，人在比什么都强。","bonus":"账本到手：带走其收支记录交给老龟，加成 50%。","unlock":"无","flagship":false},{"id":"q08","title":"送一程","fixer":"老龟","fixerNote":"平民区·修车行「龟尾」，永远在车底下","district":"城郊方向","type":"护送离城","difficulty":"中","pay":70000,"payNote":"","deadline":"三日内","brief":"有位客人要出城去赤羽方向，不想留名，也不想被记脸。我的车，你的方向盘。路上别问，别看后视镜太久，准点到。客人的规矩就是我的规矩——这一单的规矩是：当没发生过。","goal":"按约定时间将客人送达赤羽城郊交接点，平安返回。","terms":"不问身份；不接受任何绕路请求；交接点拍照即毁。","risk":"出城关卡与城郊路段各有各的耳朵；被跟踪就立刻回报。","bonus":"无痕：全程未被发现跟踪痕迹，加成 30%。","unlock":"无","flagship":false},{"id":"q09","title":"秤上的老鼠","fixer":"秤叔","fixerNote":"红花街·旧当铺「公平秤」的柜台后头","district":"红花街","type":"回收","difficulty":"低","pay":40000,"payNote":"","deadline":"无","brief":"我柜台上有个伙计，偷了我三件寄卖货跑了——义体件，来路我清清楚楚，他卖不出好价，只能蹲在红花街等下家。人我可以不要，货我要。找他，拿货。告诉他，秤叔的秤，称得出每个人的斤两。","goal":"找到伙计，追回三件寄卖货。","terms":"货为主，人为次——他要是配合，放他一条生路。","risk":"他可能已经把货押给了别人；红花街的规矩，货在谁手里谁有理，别在店里动手。","bonus":"完璧：三件货一件不少且未拆封，加成 20%。","unlock":"无","flagship":false},{"id":"q10","title":"塔里的名单","fixer":"教授","fixerNote":"新日本时代广场·二手芯片铺「百科全数」的店主","district":"月之森周边","type":"渗透调查","difficulty":"高","pay":200000,"payNote":"","deadline":"无","brief":"月之森每年都有毕业生被弦卷的「人才计划」挑走——全额奖学金、直通塔里任职，家里从此只收得到标准化的报平安邮件。有位母亲委托我查她女儿的近况，我把活转给你。别紧张，多数人只是在塔里过得很好，只是不能再联系家里人而已。多数人。","goal":"查明近三年「人才计划」入选者的实际去向，取回可交付的线索。","terms":"委托人只要女儿的下落；其余名单见好就收。","risk":"弦卷的外围安防不养闲人；这份名单本身可能就是诱饵。","bonus":"人证：带回一名入选者的亲笔讯息，加成 50%。","unlock":"无","flagship":false},{"id":"q_heist","title":"借走一段旧歌声（易碎品，勿摇晃）","fixer":"匿名","fixerNote":"仅经委托板传话，问讯报腔","district":"弦卷303酒店顶层","type":"潜入","difficulty":"极高","pay":1000000,"payNote":"基础报酬另加 300% 完工结算奖金；定金已付；保密协议单独签署。","deadline":"解锁后长期有效","brief":"一位不愿透露身份的委托人放的单：潜入指定居所，取回一只手掌大小的封蜡小盒。盒内物品不明，委托方声明无需查看、无需确认——拿到即算完成。安保等级极高。建议夜间行动。","goal":"潜入弦卷303酒店顶层居所，取回封蜡小盒并撤离。","terms":"不得携带重装武器进入建筑本体；不得与居所主人发生任何形式的接触；中间人勿扰；企业狗勿扰；警视厅相关人员勿扰。","risk":"私人安保＋智能哨戒双配置；塔的阴影里有个顶着吉祥物名字的东西，别让它看见你。","bonus":"无痕：未触发任何警报，加成 100%。","unlock":"完成2单任意委托","flagship":true}],"locationMaps":[{"id":"tokyo-central","places":[{"id":"plaza","name":"新日本时代广场","cat":"地标","group":"imperial","lon":139.7635,"lat":35.6855,"desc":"东京都最大的广场兼交通枢纽，霓虹时代重建计划的中心工程，以『新日本』纪元命名。地面层是巨型换乘枢纽，地铁、磁悬浮与高架步道三层立体交叉；广场中央的全息投影塔昼夜循环播放四大集团广告与政府公报。四大势力大厦分立四角——北为弦卷塔，东为丰川本社，西为太平洋防务总部，南为联邦科技日本区总部。市民因此戏称这里为『公司广场』。普通人心里都清楚，这座广场属于哪些人。"},{"id":"tsurumaki-tower","name":"弦卷塔","cat":"地标","group":"imperial","lon":139.7635,"lat":35.6888,"desc":"矗立于新日本时代广场北缘的东京都第一高塔，三栋通过中层巨型走廊相连的合体建筑——左塔、右塔515米，中塔777米，通体黑晶幕墙，塔尖常年隐没在雾霾与全息广告的辉光里。弦卷集团的总部所在：中塔高层以上权限逐层收紧，顶层是弦卷家族的私人领域，外人无从知晓其真貌。塔内安保由集团私兵与智能哨戒系统双层把守。坊间传言塔的地下藏着集团真正的金库与『不宜见光之物』。"},{"id":"tsukinomori","name":"月之森女子学园","cat":"学校","group":"imperial","lon":139.744,"lat":35.686,"desc":"校风严谨的私立女子学校，受弦卷集团资助。设有小学部、初中部和高中部，在读学生多为富家千金。丰川祥子曾在此就读，2050年因家中变故离校，现为无证黑户；若叶睦原在册，2050年12月底离家出走；高一A班还有已申请在外实习的长崎素世。"},{"id":"hanasakigawa","name":"花咲川女子学院","cat":"学校","group":"imperial","lon":139.7515,"lat":35.7218,"desc":"位于文京区的职业学校，校风严苛，与东京政府的警视厅与法务系统挂钩，承担定向培养任务。注重纪律和体能考核，学生大多出身赤贫或公务员家庭，多数毕业生会报考警务系统或进入地方防务部门做文职。高一B班有椎名立希与八幡海铃，初三A班是要乐奈——立希还在RING-Live!地下三层的吧台兼职。"},{"id":"ring-community","name":"RiNG社区","cat":"街区","group":"underpool","level":"区划","lbl":{"dx":-18,"dy":-6,"anchor":"end"},"lon":139.7297,"lat":35.7295,"dims":[{"k":"治安","v":"2 · 失序","d":"警视厅只在地表外围出入口设防，社区内部由各方按自己的规则管辖"},{"k":"人口","v":"约4万","d":"破产平民、海外滞留人员、底层手工艺人与无合法身份的边缘青年"},{"k":"经济","v":"赤贫～温饱","d":"黑市流通、二手乐器与零工"},{"k":"基建","v":"残缺","d":"市政维护早已停止，私接电缆挂在锈蚀钢架上，网路靠民间中继"},{"k":"势力","v":"四方分治","d":"走私团伙、黑帮、音乐社团与社区义警互不干涉；RING-Live!为中立停火区"}],"desc":"2023年大停电让池袋庞大的地下铁网络与多层商业街区彻底停摆；行政力量撤走之后，这里成了向下生长的城市。社区依托原有的铁路线向下纵深蔓延数层——从顶层尚有微光透入的废弃车站，到底层常年积水阴暗的下水道。在大企业垄断文化娱乐的时代，正规渠道充斥量产的虚拟偶像与廉价音乐，厌烦算法的年轻乐手因此在此聚集；二手实体乐器、老式效果器与民间拼装的音响在这里流通。社区的核心场馆RING-Live!坐落于地下换乘大厅的地表入口。"},{"id":"ring-live","name":"RING-Live!","cat":"场馆","group":"underpool","lbl":{"dx":18,"dy":14,"anchor":"start"},"lon":139.733,"lat":35.7282,"desc":"都筑诗船建立的第三家Live House，负责人真次凛凛子，馆名承自旧日本时期的老牌场馆『旧RiNG』。改造自旧时代建筑，地上三层地下三层共六层，是社区核心的中立停火区——严禁携带重装武器入内。这里既是Live House，也是物资集散地与黑市；一楼乐器店与旧唱片店，二楼咖啡馆，另有录音室与乐器租赁。地下三层是全社区最大的酒吧『Lust？Love？Live！』——椎名立希自2051年4月起就在那间吧台兼职并协助场务。"},{"id":"space-site","name":"SPACE 旧址","cat":"场馆","group":"underpool","lbl":{"dx":-18,"dy":-6,"anchor":"end"},"lon":139.726,"lat":35.732,"desc":"都筑诗船的第一家Live House，『大少女乐团时代』的发源地之一，曾引发女子高中生乐队热潮。2049年年末正式关闭，原址后被公司收购，改建为停车场。关闭时，RiNG社区中人都一片哀嚎。对要乐奈来说，这里是如同家一般的地方——即使关闭至今，她依然会经常在旧址门口逗留。"},{"id":"circle","name":"CiRCLE","cat":"场馆","group":"underpool","lbl":{"dx":18,"dy":-4,"anchor":"start"},"lon":139.738,"lat":35.727,"desc":"都筑诗船在关闭SPACE后开设的第二家Live House，负责人月岛麻里奈，位于RiNG社区外围。场地可容纳约500人——在娱乐财阀连锁场馆遍布东京的今天，这类坚持实体舞台的独立Live House是地下乐队稀缺的演出资源，人气很高，时常爆满。2050年6月初，CRYCHIC唯一一次Live在此举办，要乐奈在观众席听完了《春日影》；同月月底的一个雨夜，祥子也是在这里向CRYCHIC宣告退队。"},{"id":"beni-street","name":"红花街","cat":"街区","group":"underpool","level":"区划","lbl":{"dx":-16,"dy":20,"anchor":"end"},"lon":139.7225,"lat":35.7225,"dims":[{"k":"治安","v":"1 · 极危","d":"不属于任何一方管辖，纠纷靠私了；警视厅不进这条街"},{"k":"人口","v":"常驻极少 · 日流约2万","d":"小商贩、性工作者、黑超梦商人与寻医问药的伤者"},{"k":"经济","v":"温饱","d":"地摊小吃、灰色服务与廉价义体手术"},{"k":"基建","v":"残缺","d":"违章铁皮桥与规格不一的电缆，消防与急救都没有保障"},{"k":"势力","v":"无主导","d":"地头蛇按巷道收清扫费，各方默契不把冲突烧进这条街"}],"desc":"红花街本不该存在——它是在RiNG贫民区与平民区的交界缝隙里自己长出来的三不管地带。多层立体的街道与巷道里，地摊与推车商贩挤满白天，各色霓虹灯牌彻夜不熄；廉价但品控不一的义体医生藏在街巷深处。街道整体的视觉风格，与旧日本时期的歌舞伎町相似。海铃也常去夕暮老街找宇田川巴处理伤口与维护义体，巴的诊所与羽泽咖啡店比邻。"},{"id":"a-yang-clinic","name":"宇田川巴的老街诊所","cat":"店铺","group":"underpool","lbl":{"dx":-18,"dy":6,"anchor":"end"},"lon":139.7232,"lat":35.7238,"desc":"夕暮老街的独立义体与神经内科诊所，由宇田川巴主理，与羽泽咖啡店比邻。海铃经常来这里接受外伤处理与义体维护——委托中左臂挨枪的伤口处理与防弹片更换，就是在这里做的。"},{"id":"haneoka","name":"羽丘女子学园","cat":"学校","group":"underpool","lon":139.728,"lat":35.742,"desc":"校风开朗的平民女子学校，设有初中部和高中部，以丰厚的奖学金机制和免费食堂而闻名。制服颜色随学年变化是其一景——初中部紫色，高中部一年级绿色、二年级蓝色、三年级棕色。高一A班：高松灯与千早爱音（2051年4月入学）。"},{"id":"akabane","name":"赤羽街区","cat":"街区","group":"lowtown","lon":139.7205,"lat":35.776,"desc":"北区北端的旧街区。2051年3月的一个雨夜，丰川祥子拉紧兜帽，穿过霓虹灯下的小巷——夜活归途，全程警戒，她在这片街区的阴影里一步步盘算着向丰川家的复仇。"},{"id":"sakiko-rental","name":"祥子的赤羽出租屋"},{"id":"akabane-clinic","name":"赤羽黑诊所"},{"id":"rana-shifune-home","name":"乐奈与诗船的公寓"},{"id":"ring-instruments","name":"RING-Live! · 乐器店"},{"id":"ring-records","name":"RING-Live! · 旧唱片店"},{"id":"ring-cafe","name":"RING-Live! · 咖啡馆"},{"id":"ring-studio","name":"RING-Live! · 录音与租赁"},{"id":"ring-basement-bar","name":"Lust？Love？Live！"},{"id":"service-imperial-weapon","name":"皇核 · 武器店"},{"id":"service-imperial-implant","name":"皇核 · 义体医生"},{"id":"service-imperial-hospital","name":"皇核 · 医疗点"},{"id":"service-imperial-market","name":"皇核 · 垃圾商店"},{"id":"service-imperial-transit","name":"皇核 · 交通设施"},{"id":"service-underpool-weapon","name":"暗池 · 武器店"},{"id":"service-underpool-implant","name":"暗池 · 义体医生"},{"id":"service-underpool-hospital","name":"暗池 · 医疗点"},{"id":"service-underpool-market","name":"暗池 · 垃圾商店"},{"id":"servi