/* Section pages in the game menu style (DESIGN.md 10.11): a page head with tabs and one total,
   a grouped list on the left and a solid detail panel on the right. Shared by the journal,
   network and archive pages; motion is played from terminal.js. */
/* Also beats the terminal's generic page column (.t2051x .page). */
.t2051x .sec-page,
.sec-page {
  display: grid;
  grid-template-rows: auto minmax(0,1fr);
  gap: 12px;
  height: 100%;
  min-height: 0;
  padding: 12px 8px 8px;
  box-sizing: border-box;
  color: var(--cxx-on-canvas);
  font: 16px/1.6 var(--cxx-font-ui);
}

.sec-page * {
  box-sizing: border-box;
}

.sec-page :is(h1,h2,h3,p) {
  margin: 0;
}

.sec-page button {
  font: inherit;
  cursor: pointer;
}

.sec-page button:disabled {
  cursor: default;
  opacity: .48;
}

.sec-page :is(button,summary,input):focus-visible {
  outline: 2px solid var(--cxx-interactive);
  outline-offset: -2px;
}

/* ---------- Page head ---------- */
.sec-head {
  display: flex;
  align-items: flex-end;
  gap: 16px;
  min-width: 0;
}

.sec-title {
  min-width: 0;
}

.sec-eyebrow {
  display: block;
  color: var(--cxx-on-canvas-muted);
  font: var(--cxx-weight-latin) 12px/1.4 var(--cxx-font-label);
  letter-spacing: var(--cxx-track);
  text-transform: uppercase;
}

.sec-title h1 {
  color: var(--cxx-heading);
  font-size: var(--cxx-size-title);
  font-weight: var(--cxx-weight-heading);
  line-height: 1.15;
  white-space: nowrap;
}

.sec-grow {
  flex: 1;
}

.sec-tabs {
  position: relative;
  display: flex;
  gap: 2px;
  min-width: 0;
}

.sec-page .sec-tabs button {
  min-height: 44px;
  padding: 0 14px;
  border: 0;
  border-bottom: 2px solid transparent;
  border-radius: 0;
  background: none;
  color: var(--cxx-on-canvas-muted);
  font-size: 16px;
  white-space: nowrap;
  transition: color .16s;
}

.sec-page .sec-tabs button[aria-pressed=true] {
  color: var(--cxx-heading);
  font-weight: 600;
}

/* Until the sliding bar is placed, the current tab carries its own underline. */
.sec-page .sec-tabs:not([data-ink]) button[aria-pressed=true] {
  border-bottom-color: var(--cxx-structure);
}

.sec-tabs-ink {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 0;
  height: 2px;
  background: var(--cxx-structure);
  transform-origin: left;
  pointer-events: none;
}

@media (hover:hover) and (pointer:fine) {
  .sec-page .sec-tabs button:hover:enabled {
    color: var(--cxx-on-canvas);
  }
}

.sec-figure {
  display: grid;
  justify-items: end;
  flex: none;
}

.sec-figure small {
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
}

.sec-figure strong {
  color: var(--cxx-on-canvas);
  font: var(--cxx-weight-latin) 28px/1 var(--cxx-font-latin);
  white-space: nowrap;
}

/* ---------- List ---------- */
.sec-body {
  display: grid;
  grid-template-columns: 380px minmax(0,1fr);
  gap: 20px;
  min-height: 0;
}

.sec-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
}

.sec-list>* {
  flex: none;
}

.sec-group {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 8px 0 2px;
  color: var(--cxx-heading);
  font: var(--cxx-weight-latin) 13px/1.3 var(--cxx-font-label);
  letter-spacing: var(--cxx-track);
}

.sec-group::before {
  content: "▾";
}

.sec-page .sec-row {
  display: grid;
  grid-template-columns: 16px minmax(0,1fr) auto;
  align-items: center;
  gap: 2px 10px;
  width: 100%;
  min-height: 52px;
  margin: 0;
  padding: 6px 12px;
  border: 0;
  border-left: 3px solid transparent;
  border-radius: 0;
  background: color-mix(in srgb, var(--cxx-raised) 55%, transparent);
  color: var(--cxx-text);
  text-align: left;
  transition: background-color .16s,border-color .16s;
}

.sec-row>strong {
  min-width: 0;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.sec-row>small {
  grid-column: 2 / -1;
  min-width: 0;
  color: var(--cxx-muted);
  font-size: 13px;
  line-height: 1.4;
}

.sec-icon {
  width: 10px;
  height: 10px;
  margin-left: 2px;
  border: 1.5px solid var(--cxx-attention);
  transform: rotate(45deg);
}

.sec-icon.is-main {
  background: var(--cxx-attention);
}

.sec-chip {
  display: inline-flex;
  align-items: center;
  min-height: 22px;
  padding: 0 8px;
  border: 1px solid var(--cxx-line);
  color: var(--cxx-muted);
  font-size: 13px;
  white-space: nowrap;
}

.sec-chip.is-attention {
  border-color: var(--cxx-attention);
  color: var(--cxx-attention);
}

.sec-page .sec-row[aria-pressed=true] {
  border-left-color: var(--cxx-interactive);
  background: var(--cxx-selected);
  color: var(--cxx-on-selected);
  box-shadow: inset 0 0 0 1px var(--cxx-interactive);
}

/* Yellow marks the selected row with the interactive fill (DESIGN.md 10.1). */
:root[data-cxx-theme=yellow] .sec-page .sec-row[aria-pressed=true] {
  background: var(--cxx-interactive);
  color: var(--cxx-on-interactive);
}

.sec-row[aria-pressed=true]>small {
  color: inherit;
}

.sec-row[aria-pressed=true] :is(.sec-chip,.sec-icon) {
  border-color: currentColor;
  color: inherit;
}

.sec-row[aria-pressed=true] .sec-icon.is-main {
  background: currentColor;
}

@media (hover:hover) and (pointer:fine) {
  .sec-page .sec-row:hover:enabled:not([aria-pressed=true]) {
    border-left-color: var(--cxx-structure);
    background: color-mix(in srgb, var(--cxx-structure) 14%, transparent);
  }
}

.sec-empty {
  padding: 20px 12px;
  color: var(--cxx-on-canvas-muted);
}

/* ---------- Detail panel ---------- */
.sec-detail {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  min-height: 0;
  padding: 18px 22px;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-panel);
  color: var(--cxx-text);
  overflow: hidden;
}

.sec-detail h2 {
  color: var(--cxx-heading);
  font-size: 26px;
  font-weight: var(--cxx-weight-heading);
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.sec-detail .sec-eyebrow {
  color: var(--cxx-muted);
}

.sec-scroll {
  display: flex;
  flex-direction: column;
  gap: 12px;
  flex: 1;
  min-height: 0;
  overflow: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
  overflow-wrap: anywhere;
}

.sec-scroll>* {
  flex: none;
}

.sec-objective {
  padding: 10px 14px;
  border-left: 3px solid var(--cxx-structure);
  background: color-mix(in srgb, var(--cxx-structure) 7%, transparent);
}

.sec-objective small {
  display: block;
  color: var(--cxx-muted);
  font-size: 13px;
}

.sec-terms {
  display: grid;
  grid-template-columns: repeat(3,minmax(0,1fr));
  gap: 8px;
}

.sec-terms>div {
  padding: 8px 10px;
  border: 1px solid var(--cxx-line);
}

.sec-terms small {
  display: block;
  color: var(--cxx-muted);
  font-size: 13px;
}

.sec-terms strong {
  display: block;
  font-size: 18px;
  font-weight: 600;
}

.sec-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  flex: none;
  margin-top: auto;
}

.sec-page .sec-button {
  min-height: 44px;
  padding: 0 16px;
  border: 1px solid var(--cxx-line);
  border-radius: 0;
  background: var(--cxx-panel);
  color: var(--cxx-text);
  white-space: nowrap;
  transition: background-color .16s,border-color .16s,filter .16s;
}

.sec-page .sec-button.is-primary {
  flex: 1;
  border-color: var(--cxx-interactive);
  background: var(--cxx-interactive);
  color: var(--cxx-on-interactive);
  font-weight: 700;
}

@media (hover:hover) and (pointer:fine) {
  .sec-page .sec-button:hover:enabled {
    border-color: var(--cxx-interactive);
  }

  .sec-page .sec-button.is-primary:hover:enabled {
    filter: brightness(1.1);
  }
}

.sec-link {
  justify-self: start;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--cxx-interactive);
  text-align: left;
}

@supports (corner-shape: bevel) {
  .sec-detail {
    border-radius: var(--cxx-cut-m) 0;
    corner-shape: bevel;
  }

  .sec-page .sec-button {
    border-radius: var(--cxx-cut-s) 0;
    corner-shape: bevel;
  }
}

/* ---------- Narrow: one column, the list first and the detail after a choice ---------- */
@media (max-width:700px) {
  .sec-page {
    gap: 8px;
    padding: 8px 4px 4px;
  }

  .sec-head {
    flex-wrap: wrap;
    align-items: center;
    gap: 2px 12px;
  }

  .sec-title h1 {
    font-size: var(--cxx-size-title-sm);
  }

  .sec-tabs {
    overflow-x: auto;
    scrollbar-width: none;
  }

  .sec-head .sec-tabs {
    order: 5;
    width: 100%;
  }

  .sec-page .sec-tabs button {
    flex: none;
    padding: 0 10px;
  }

  .sec-figure {
    grid-auto-flow: column;
    align-items: baseline;
    gap: 6px;
    margin-left: auto;
  }

  .sec-figure strong {
    font-size: 20px;
  }

  .sec-body {
    grid-template-columns: minmax(0,1fr);
  }

  .sec-page[data-view=list] .sec-detail,
  .sec-page[data-view=detail] .sec-list-pane {
    display: none;
  }

  .sec-detail {
    padding: 12px 14px;
  }

  .sec-detail h2 {
    font-size: 22px;
  }

  .sec-terms strong {
    font-size: 16px;
  }
}

/* ---------- Archive: categories, record rows and the record panel ---------- */
.archive-body {
  display: grid;
  grid-template-columns: 220px 320px minmax(0,1fr);
  gap: 16px;
  min-height: 0;
}

.archive-side {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}

.archive-kinds {
  display: grid;
  gap: 2px;
}

.sec-page .archive-kinds button {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 44px;
  padding: 0 12px;
  border: 0;
  border-left: 3px solid transparent;
  border-radius: 0;
  background: none;
  color: var(--cxx-on-canvas-muted);
  text-align: left;
  transition: background-color .16s,color .16s;
}

.sec-page .archive-kinds button[aria-pressed=true] {
  border-left-color: var(--cxx-structure);
  background: color-mix(in srgb, var(--cxx-structure) 10%, transparent);
  color: var(--cxx-heading);
}

.archive-kinds b {
  font: var(--cxx-weight-latin) 16px/1 var(--cxx-font-latin);
}

@media (hover:hover) and (pointer:fine) {
  .sec-page .archive-kinds button:hover:not([aria-pressed=true]) {
    color: var(--cxx-on-canvas);
  }
}

.archive-search label {
  display: block;
  margin-bottom: 4px;
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
}

.sec-page .archive-search input {
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--cxx-line);
  border-radius: 0;
  background: var(--cxx-canvas);
  color: var(--cxx-on-canvas);
  font: inherit;
  font-size: 16px;
}

.archive-note {
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
  line-height: 1.7;
}

.archive-row .archive-icon {
  border-color: var(--cxx-structure);
}

.archive-code {
  color: var(--cxx-muted);
  font: var(--cxx-weight-latin) 14px/1 var(--cxx-font-latin);
}

.sec-row[aria-pressed=true] .archive-code {
  color: inherit;
}

.sec-page .archive-detail {
  gap: 0;
  padding: 0;
}

.archive-figure {
  position: relative;
  flex: none;
  height: 38%;
  min-height: 150px;
  max-height: 260px;
  overflow: hidden;
  border-bottom: 1px solid var(--cxx-line);
  background: var(--cxx-raised) center / cover no-repeat;
}

.archive-figure img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Scene treatment per theme (DESIGN.md 10.8): yellow duotone, night desaturated. */
:root[data-cxx-theme=yellow] .archive-figure {
  filter: url(#cxx-scene-yellow);
}

:root[data-cxx-theme=night] .archive-figure {
  filter: grayscale(1) brightness(.7);
}

.archive-detail .sec-scroll {
  padding: 16px 22px 0;
}

.archive-detail .sec-actions {
  align-items: center;
  padding: 12px 22px 18px;
}

.archive-position {
  padding: 0 4px;
  color: var(--cxx-muted);
  font: var(--cxx-weight-latin) 15px/1 var(--cxx-font-latin);
}

.archive-region {
  color: var(--cxx-muted);
}

.archive-summary {
  line-height: 1.8;
}

.sec-page :is(.archive-back,.net-back) {
  display: none;
  align-self: flex-start;
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--cxx-interactive);
}

@media (max-width:700px) {
  .archive-body {
    grid-template-columns: minmax(0,1fr);
    grid-template-rows: auto minmax(0,1fr);
    gap: 8px;
  }

  .archive-side {
    gap: 6px;
  }

  .archive-kinds {
    grid-template-columns: repeat(3,minmax(0,1fr));
  }

  .sec-page .archive-kinds button {
    justify-content: center;
    gap: 6px;
    padding: 0 6px;
    border-left: 0;
    border-bottom: 2px solid transparent;
  }

  .sec-page .archive-kinds button[aria-pressed=true] {
    border-bottom-color: var(--cxx-structure);
  }

  .archive-search label,
  .archive-note {
    display: none;
  }

  .archive-page[data-view=detail] .archive-side {
    display: none;
  }

  .archive-page[data-view=detail] .archive-body {
    grid-template-rows: minmax(0,1fr);
  }

  .sec-page :is(.archive-back,.net-back) {
    display: inline-flex;
    align-items: center;
  }

  .archive-figure {
    min-height: 120px;
    height: 30%;
  }

  .archive-detail .sec-scroll {
    padding: 8px 14px 0;
  }

  .archive-detail .sec-actions {
    padding: 10px 14px 12px;
  }
}

/* ---------- Network: contacts, mail and city messages ---------- */
#terminal-module-network {
  height: 100%;
  min-height: 0;
  overflow: hidden;
  padding: 0;
}

.net-view {
  display: grid;
  grid-template-rows: minmax(0,1fr);
  min-height: 0;
}

.net-city {
  display: grid;
  grid-template-rows: auto minmax(0,1fr);
  gap: 8px;
  min-height: 0;
}

.net-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px 8px;
  padding-bottom: 8px;
}

.net-status {
  flex: 1 1 100%;
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
  line-height: 1.5;
}

.sec-page .net-tools .sec-button {
  flex: 1;
  padding: 0 10px;
}

.sec-page .net-contact {
  grid-template-columns: 48px minmax(0,1fr);
  min-height: 64px;
}

.net-contact .net-avatar {
  grid-row: 1 / span 2;
}

.net-contact>small {
  grid-column: 2;
}

.net-avatar {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  overflow: hidden;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-raised);
  color: var(--cxx-heading);
  font-size: 20px;
}

.net-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: top;
}

.net-avatar.is-large {
  flex: none;
  width: 96px;
  height: 96px;
  font-size: 36px;
}

.net-contact.is-locked>strong {
  color: var(--cxx-muted);
}

.net-contact.is-locked img {
  filter: grayscale(1) brightness(.6);
}

.net-person {
  display: flex;
  align-items: center;
  gap: 16px;
}

:is(.net-state,.net-note) {
  color: var(--cxx-muted);
  font-size: 14px;
}

.net-log {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.net-msg {
  max-width: 78%;
  padding: 8px 12px;
  background: var(--cxx-raised);
  font-size: 15px;
  line-height: 1.7;
}

.net-msg b {
  display: block;
  color: var(--cxx-heading);
  font-size: 13px;
}

.net-msg.is-mine {
  align-self: flex-end;
  background: color-mix(in srgb, var(--cxx-interactive) 14%, var(--cxx-panel));
}

:is(.net-mail-body,.net-article) {
  line-height: 1.85;
  white-space: pre-line;
}

.net-lead {
  font-weight: 600;
}

.net-floors {
  display: grid;
}

.net-floor {
  padding: 10px 0;
  border-top: 1px solid var(--cxx-line);
}

.net-floor b {
  display: block;
  color: var(--cxx-heading);
  font-size: 13px;
}

.net-floor span {
  white-space: pre-line;
}

.net-summary {
  margin-top: 10px;
  border-top: 1px solid var(--cxx-line);
}

.net-summary>summary {
  display: flex;
  align-items: center;
  min-height: 44px;
  color: var(--cxx-interactive);
  font-size: 14px;
  cursor: pointer;
}

.net-radio {
  min-height: 0;
  overflow: auto;
}

/* ---------- Character page: the section head above the shared player panel ---------- */
.player-head {
  flex: none;
  padding: 12px 8px 0;
}

@media (max-width:700px) {
  .player-head {
    padding: 8px 4px 0;
  }
}
/* Commission journal (DESIGN.md 10.11). Page head, list rows, detail panel and buttons come
   from sections.css; this sheet keeps what only the journal has. */

#t2051x-terminal[data-page=operations] .workspace {
  padding: 0;
  overflow: hidden;
  min-height: 0;
}

#t2051x-terminal[data-page=operations] .terminal-history-back {
  display: none;
}

#terminal-module-operations {
  height: 100%;
  min-height: 0;
  overflow: hidden;
  padding: 0;
}

.cxx-journal {
  position: relative;
  isolation: isolate;
  background: var(--cxx-canvas);
}

.cxx-journal small {
  font-size: 13px;
}

/* ---------- List column ---------- */
.journal-index {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}

.journal-list {
  flex: 1;
}

.journal-row-title {
  color: inherit;
}

.journal-index-foot {
  display: flex;
  align-items: baseline;
  gap: 10px;
  flex: none;
  padding: 10px 4px 0;
  border-top: 1px solid var(--cxx-line);
}

.journal-index-foot small {
  color: var(--cxx-on-canvas-muted);
}

.journal-index-foot>span {
  min-width: 0;
  overflow: hidden;
  color: var(--cxx-on-canvas);
  font-size: 13px;
  white-space: nowrap;
  text-overflow: ellipsis;
}

/* ---------- Detail panel ---------- */
.journal-detail-bar {
  display: flex;
  align-items: center;
  gap: 12px;
  flex: none;
}

.cxx-journal .journal-back {
  display: none;
}

.journal-detail-bar .journal-back {
  min-height: 44px;
  padding: 0;
  border: 0;
  background: none;
  color: var(--cxx-interactive);
}

.journal-kicker {
  color: var(--cxx-muted);
  font-size: 14px;
}

.journal-objective p {
  color: var(--cxx-text);
  line-height: 1.65;
}

.cxx-journal .journal-copy h3 {
  color: var(--cxx-heading);
  font-size: 15px;
  font-weight: 600;
}

:is(.journal-brief,.journal-facts) {
  font-size: 16px;
  line-height: 1.85;
  white-space: pre-line;
}

.cxx-journal .journal-note {
  color: var(--cxx-muted);
  font-size: 13px;
  line-height: 1.7;
}

:is(.journal-terms,.journal-more) {
  padding: 4px 0;
  border-top: 1px solid var(--cxx-line);
}

:is(.journal-terms,.journal-more) summary {
  display: flex;
  align-items: center;
  min-height: 44px;
  color: var(--cxx-interactive);
  font-size: 14px;
  cursor: pointer;
}

:is(.journal-terms,.journal-more) summary::before {
  content: "＋";
  margin-right: 9px;
}

:is(.journal-terms,.journal-more)[open] summary::before {
  content: "－";
}

.journal-terms p {
  margin: 0 0 8px;
}

.journal-more>button {
  min-height: 44px;
  margin: 0 8px 8px 0;
  padding: 0 14px;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-panel);
  color: var(--cxx-text);
}

.journal-reason {
  color: var(--cxx-attention);
  font-size: 13px;
}

.journal-welcome {
  color: var(--cxx-muted);
}

.journal-welcome:first-child {
  color: var(--cxx-heading);
  font-size: 20px;
}

/* ---------- Status and confirmation ---------- */
.journal-status {
  flex: none;
  min-height: 0;
  color: var(--cxx-on-canvas-muted);
  font-size: 13px;
  line-height: 1.5;
}

.journal-status:empty,
.journal-status:has(>span:empty:only-child) {
  display: none;
}

.journal-status[data-error=true] {
  color: var(--cxx-danger);
}

.journal-status button {
  min-height: 44px;
  padding: 0 10px;
  font-size: 16px;
  border: 0;
  background: none;
  color: var(--cxx-interactive);
  text-decoration: underline;
}

.cxx-journal:has(>.journal-status:not(:empty)) {
  grid-template-rows: auto minmax(0,1fr) auto;
}

.journal-empty {
  padding: 20px 12px;
  color: var(--cxx-on-canvas-muted);
}

.journal-confirm {
  position: absolute;
  inset: 0;
  z-index: 3;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 12px;
  padding: clamp(20px,6%,72px);
  overflow: auto;
  background: var(--cxx-panel);
  color: var(--cxx-text);
}

.journal-confirm h2 {
  color: var(--cxx-heading);
  font-size: 26px;
  font-weight: var(--cxx-weight-heading);
}

.journal-confirm strong {
  color: var(--cxx-on-canvas);
  font-size: 18px;
}

.journal-confirm p {
  font-size: 15px;
}

.journal-confirm>div:last-child {
  display: flex;
  gap: 12px;
  margin-top: 10px;
}

.journal-change {
  font-size: 13px;
  overflow-wrap: anywhere;
}

/* ---------- Narrow ---------- */
@media (max-width:700px) {
  .cxx-journal .journal-back {
    display: inline-flex;
    align-items: center;
  }

  .journal-actions {
    padding-bottom: env(safe-area-inset-bottom,0px);
  }

  .journal-confirm {
    justify-content: flex-start;
    padding: 22px;
  }
}

@media (max-height:520px) {
  .journal-index-foot {
    display: none;
  }

  /* Short landscape screens keep only the filter tabs in the head. */
  .cxx-journal .journal-head :is(.sec-title,.journal-wallet) {
    display: none;
  }

  .journal-confirm {
    justify-content: flex-start;
    padding: 18px;
  }
}

#t2051x-terminal[data-page=operations] button:not(:focus-visible) {
  transition: translate 140ms cubic-bezier(.23,1,.32,1),background-color 140ms,border-color 140ms;
}

#t2051x-terminal[data-page=operations] button:active:not(:disabled):not(:focus-visible) {
  translate: 0 1px;
  transition-duration: 0s;
}

@media (prefers-reduced-motion:reduce) {
  #t2051x-terminal[data-page=operations] button {
    transition: none!important;
    translate: none!important;
  }
