/* Standalone terminal on phones: the system directory as one row of six. */
@media (max-width:700px) {
  #t2051x-terminal .system-nav {
    display: grid;
    grid-template-columns: repeat(6,minmax(0,1fr));
    gap: 3px;
  }

  #t2051x-terminal .system-nav .nav-item {
    min-width: 0;
    padding: 5px 2px;
    font-size: 16px;
  }

  #t2051x-terminal .system-nav .nav-heading {
    display: none;
  }
}

@media (max-height:520px) {
  #t2051x-terminal[data-page=operations] .terminal-foot {
    display: none;
  }
}
html[data-cxx-embedded=true] {
  height: 100%;
  margin: 0;
  overflow: hidden;
  color-scheme: dark;
  background: var(--cxx-ink)!important;
}

html[data-cxx-embedded=true] body {
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--cxx-ink)!important;
}

html[data-cxx-embedded=true] #t2051x-root {
  height: 100%;
  min-height: 0;
  background: transparent;
}

html[data-cxx-embedded=true] #t2051x-terminal {
  position: absolute!important;
  inset: 0!important;
  transform: none!important;
  width: 100%!important;
  height: 100%!important;
  min-height: 0!important;
  max-height: none!important;
  display: flex;
  flex-direction: column;
  border: 0;
  background: transparent!important;
  padding: 0;
}

html[data-cxx-embedded=true] #t2051x-terminal[hidden] {
  display: none!important;
}

html[data-cxx-embedded=true] #t2051x-terminal>.masthead {
  display: none!important;
}

html[data-cxx-embedded=true] #t2051x-system-nav {
  display: none!important;
}

html[data-cxx-embedded=true] .terminal-foot {
  display: none!important;
}

html[data-cxx-embedded=true] .terminal-scene {
  display: none!important;
}

html[data-cxx-embedded=true] #t2051x-fab {
  display: none!important;
}

html[data-cxx-embedded=true] .terminal-history-back {
  display: none!important;
}

html[data-cxx-embedded=true] #t2051x-workspace {
  width: 100%;
  height: 100%;
  min-height: 0;
  flex: 1;
  margin: 0;
  padding: 0;
  overflow: auto;
  grid-column: auto;
  background: transparent;
}

html[data-cxx-embedded=true] #t2051x-workspace>.page {
  min-height: 100%;
  height: auto;
  padding: 12px;
  background: transparent;
}

/* The journal, network and archive pages scroll inside their list and detail columns, so they keep the workspace height as in the standalone terminal. */
html[data-cxx-embedded=true] #t2051x-workspace>#terminal-module-operations,
html[data-cxx-embedded=true] #t2051x-workspace>#terminal-module-network {
  height: 100%;
