* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  justify-content: center;
  display: block;
  margin: 0;
  padding: 0;
  background: transparent;
  color: var(--cxx-text);
  font-family: var(--cxx-font-ui);
}

@keyframes gentleBob {
  0%, 100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-4px);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes heartFloat {
  0% {
    transform: translateY(0) scale(1) rotate(0deg);
    opacity: .9;
  }

  100% {
    transform: translateY(-70px) scale(.15) rotate(35deg);
    opacity: 0;
  }
}

@keyframes shimmer {
  0% {
    background-position: -200% center;
  }

  100% {
    background-position: 200% center;
  }
}

@keyframes stampPress {
  0% {
    transform: scale(1.8) rotate(-15deg);
    opacity: 0;
  }

  60% {
    transform: scale(.95) rotate(2deg);
    opacity: 1;
  }

  100% {
    transform: scale(1) rotate(0deg);
    opacity: 1;
  }
}

@keyframes tapeShine {
  0% {
    left: -100%;
  }

  100% {
    left: 200%;
  }
}

@keyframes marquee {
  0% {
    transform: translateX(0);
  }

  100% {
    transform: translateX(-50%);
  }
}

@keyframes sway {
  0%, 100% {
    transform: rotate(-2deg);
  }

  50% {
    transform: rotate(2deg);
  }
}

@keyframes pulseRose {
  0%, 100% {
    box-shadow: 0 0 8px color-mix(in srgb, var(--cxx-red) 15.00%, transparent);
  }

  50% {
    box-shadow: 0 0 24px color-mix(in srgb, var(--cxx-red) 40.00%, transparent);
  }
}

@keyframes floatSticker {
  0%, 100% {
    transform: rotate(var(--rot)) translateY(0);
  }

  50% {
    transform: rotate(var(--rot)) translateY(-3px);
  }
}

@keyframes sparkle {
  0%, 100% {
    opacity: .3;
  }

  50% {
    opacity: .9;
  }
}

@keyframes peekFlip {
  0% {
    transform: rotateY(0deg);
  }

  30% {
    transform: rotateY(32deg);
  }

  50% {
    transform: rotateY(28deg);
  }

  70% {
    transform: rotateY(18deg);
  }

  100% {
    transform: rotateY(0deg);
  }
}

@keyframes lockShake {
  0%, 100% {
    transform: translateX(0);
  }

  20% {
    transform: translateX(-2px) rotate(-0.5deg);
  }

  40% {
    transform: translateX(2px) rotate(0.5deg);
  }

  60% {
    transform: translateX(-1.5px);
  }

  80% {
    transform: translateX(1px);
  }
}

@keyframes lockFade {
  0% {
    opacity: 0;
    transform: translate(-50%,-50%) scale(0.5);
  }

  30% {
    opacity: 1;
    transform: translate(-50%,-50%) scale(1.1);
  }

  60% {
    opacity: 1;
    transform: translate(-50%,-50%) scale(1);
  }

  100% {
    opacity: 0;
    transform: translate(-50%,-50%) scale(0.9);
  }
}

.diary {
  position: relative;
  width: 100%;
  max-width: none;
  border: 1px solid var(--cxx-line);
  border-top: 0;
  border-radius: 0;
  background: var(--cxx-ink);
  box-shadow: none;
  overflow: visible;
}

.diary::before {
  content: '';
  position: absolute;
  inset: 0;
  background-image: url("data:image/svg+xml,%3Csvg width='100' height='100' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence baseFrequency='0.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100' height='100' filter='url(%23n)' opacity='0.03'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 1;
  background: repeating-linear-gradient(0deg,transparent 0 31px,color-mix(in srgb, var(--cxx-red) 2.40%, transparent) 31px 32px);
  opacity: 1;
  display: none;
}

.diary::after {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  z-index: 2;
  pointer-events: none;
  width: 24px;
  background: repeating-linear-gradient(0deg,transparent 0 7px,color-mix(in srgb, var(--cxx-red) 20.00%, transparent) 7px 8px,transparent 8px 13px),linear-gradient(90deg,var(--cxx-ink),var(--cxx-ink));
  border-right: 1px solid var(--cxx-line);
  display: none;
}

.bg-pattern {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-position: 0 0,14px 14px;
  background-image: linear-gradient(color-mix(in srgb, var(--cxx-red) 4.00%, transparent) 1px,transparent 1px),linear-gradient(90deg,color-mix(in srgb, var(--cxx-red) 4.00%, transparent) 1px,transparent 1px);
  background-size: 28px 28px;
  opacity: .3;
}

.binding-holes {
  position: absolute;
  left: 8px;
  top: 0;
  bottom: 0;
  width: 12px;
  z-index: 3;
  pointer-events: none;
  flex-direction: column;
  align-items: center;
  justify-content: space-evenly;
  padding: 30px 0;
  display: none;
}

.diary-stage {
  position: relative;
  z-index: 4;
  height: auto;
  min-height: 0;
  overflow: visible;
}

.v-list {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  transition: opacity 0.35s ease,transform 0.35s ease;
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
  opacity: 1;
  transform: translateY(0);
  z-index: 2;
}

.v-detail {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  transition: opacity 0.35s ease,transform 0.35s ease;
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
  opacity: 0;
  transform: translateY(20px);
  pointer-events: none;
  z-index: 1;
}

.v-list::-webkit-scrollbar {
  width: 4px;
}

.v-detail::-webkit-scrollbar {
  width: 4px;
}

.v-list::-webkit-scrollbar-thumb {
  background: var(--cxx-line);
  border-radius: 10px;
}

.v-detail::-webkit-scrollbar-thumb {
  background: var(--cxx-line);
  border-radius: 10px;
}

.diary.is-detail .v-list {
  opacity: 0;
  transform: translateY(-20px);
  pointer-events: none;
  z-index: 1;
}

.diary.is-detail .v-detail {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
  z-index: 2;
}

.washi-header {
  overflow: hidden;
  position: relative;
  border-left: 3px solid var(--cxx-red);
  border-radius: 2px;
  text-align: left;
  margin: 0;
  padding: 23px 24px 8px;
  background: none;
  border: 0;
  box-shadow: none;
  transform: none;
}

.washi-header::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(90deg,transparent 0 10px,color-mix(in srgb, var(--cxx-red) 5.00%, transparent) 10px 11px);
}

.washi-header::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 35%;
  height: 100%;
  pointer-events: none;
  opacity: .2;
  background: linear-gradient(90deg,transparent,color-mix(in srgb, var(--cxx-red) 32.00%, transparent),transparent);
  animation: cp-status-scan 15s linear infinite;
  display: none;
}

.washi-title {
  font-size: 0.95em;
  font-weight: 900;
  font-family: var(--cxx-font-ui);
  font: 600 19px var(--cxx-ui);
  letter-spacing: .1em;
  color: var(--cxx-text);
}

.diary-date-line {
  text-align: right;
  font-size: 13px;
  font-style: normal;
  font-family: var(--cxx-font-mono);
  margin: 0 24px 20px;
  color: var(--cxx-muted);
  font: 13px var(--cxx-mono);
  letter-spacing: .15em;
}

.ruled-area {
  position: relative;
  padding: 0 24px 24px;
}

.ruled-area::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  width: 1px;
  left: 30px;
  background: var(--cxx-line);
  opacity: 1;
  display: none;
}

.char-cards {
  flex-direction: column;
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 8px;
}

.char-card {
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  position: relative;
  border-radius: 2px;
  transition: background .2s,border-color .2s;
  min-width: 0;
  min-height: 80px;
  padding: 12px;
  background: var(--cxx-panel);
  border: 1px solid var(--cxx-line);
  box-shadow: none;
  transform: none;
  animation: none;
}

.char-card::before {
  content: '';
  position: absolute;
  z-index: 2;
  top: 0;
  left: 0;
  border-radius: 0;
  transform: none;
  opacity: .8;
  transition: width .35s ease;
  background: var(--cxx-red);
  width: 20px;
  height: 1px;
}

.char-card:nth-child(1)::before {
  background: var(--cxx-line);
}

.char-card:nth-child(2)::before {
  background: var(--cxx-status-accent-light);
}

.char-card:nth-child(3)::before {
  background: var(--cxx-status-accent-panel);
}

.char-card:nth-child(4)::before {
  background: var(--cxx-status-selected-panel);
}

.char-card:nth-child(5)::before {
  background: color-mix(in srgb, var(--cxx-cyan) 25%, var(--cxx-panel));
}

.char-card:nth-child(6)::before {
  background: color-mix(in srgb, var(--cxx-yellow) 27%, var(--cxx-panel));
  left: 30px;
  transform: rotate(1deg);
}

.char-card:nth-child(7)::before {
  background: var(--cxx-line);
  left: 15px;
  transform: rotate(-3deg);
}

.char-card:nth-child(8)::before {
  background: var(--cxx-status-accent-light);
  left: 25px;
  transform: rotate(2deg);
}

.char-card:nth-child(9)::before {
  background: var(--cxx-status-accent-panel);
  left: 35px;
  transform: rotate(-1deg);
}

.char-card:nth-child(10)::before {
  background: var(--cxx-status-selected-panel);
  left: 18px;
  transform: rotate(1.5deg);
}

.char-card:active {
  transform: translateY(0) rotate(0deg);
}

.char-card .pen-mark {
  position: absolute;
  bottom: 2px;
  left: 14px;
  right: 14px;
  height: 2px;
  border-radius: 1px;
  opacity: 0.4;
}

.card-polaroid {
  flex-shrink: 0;
  transition: all 0.4s;
  border-color: var(--cxx-line);
  border-radius: 2px;
  box-shadow: none;
  width: 44px;
  height: 52px;
  min-width: 44px;
  padding: 0;
  border: 1px solid var(--cxx-line);
  background: var(--cxx-panel);
  transform: none;
}

.card-avatar {
  width: 100%;
  height: 100%;
  border-radius: 1px;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  animation: none;
  filter: saturate(.8) contrast(1.04);
}

.card-info {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.card-top {
  display: flex;
  align-items: center;
  min-width: 0;
  flex-wrap: wrap;
  gap: 3px 8px;
}

.card-name {
  font-size: 16px;
  font-weight: 900;
  font-family: var(--cxx-font-ui);
  letter-spacing: .03em;
  overflow-wrap: anywhere;
  color: var(--cxx-text);
  font: 600 16px var(--cxx-ui);
}

.card-stamp {
  font-weight: 800;
  padding: 2px 8px;
  letter-spacing: 1px;
  border: 1.5px solid;
  white-space: nowrap;
  border-width: 1px;
  border-radius: 2px;
  font-size: 10px;
  color: var(--cxx-muted);
  border-color: var(--cxx-line);
  background: transparent;
  transform: none;
}

.card-bar-row {
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-track {
  flex: 1;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  height: 2px;
  background: color-mix(in srgb, var(--cxx-red-soft) 5.10%, transparent);
}

.card-fill {
  height: 100%;
  transition: width 1.2s cubic-bezier(0.4,0,0.2,1);
  position: relative;
  border-radius: 0;
  background: var(--cxx-red);
  animation: none;
}

.card-fill::after {
  content: '';
  position: absolute;
  top: 1px;
  left: 2px;
  right: 2px;
  height: 3px;
  background: linear-gradient(180deg,color-mix(in srgb, var(--cxx-red-soft) 45.00%, transparent),transparent);
  border-radius: 3px;
  display: none;
}

.card-val {
  font-size: 0.72em;
  font-weight: 800;
  min-width: 35px;
  text-align: right;
  font-family: var(--cxx-font-mono);
}

.card-arrow {
  transition: all 0.3s;
  flex-shrink: 0;
  color: var(--cxx-red);
  font-size: 1.1em;
}

.char-card:hover .card-arrow {
  color: var(--cxx-red);
  transform: translateX(4px);
}

.heart-p {
  position: absolute;
  color: var(--cxx-red);
  pointer-events: none;
  animation: heartFloat 3s ease-out forwards;
  z-index: 5;
  opacity: 0;
  font-size: 10px;
}

.detail-page {
  flex-direction: column;
  display: grid;
  grid-template-columns: minmax(240px,.9fr) minmax(0,1.1fr);
  gap: 24px;
  padding: 0 24px 24px;
  height: auto;
  min-height: 0;
}

.detail-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  grid-column: 1/-1;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 0;
  border-bottom: 1px solid var(--cxx-line);
  gap: 12px;
}

.back-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 14px;
  cursor: pointer;
  font-family: var(--cxx-font-ui);
  font-size: 0.76em;
  font-weight: 700;
  transition: all 0.3s;
  background: var(--cxx-ink);
  border: 1px solid var(--cxx-line);
  border-radius: 2px;
  color: var(--cxx-cyan);
  box-shadow: none;
}

.back-btn:hover {
  color: var(--cxx-red);
  transform: translateX(-3px);
  background: var(--cxx-selected-panel);
  border-color: var(--cxx-cyan);
  box-shadow: none;
}

.back-btn svg {
  width: 14px;
  height: 14px;
  fill: currentColor;
}

.dot-n {
  cursor: pointer;
  transition: all 0.3s;
  border-radius: 1px;
  position: relative;
  min-width: 24px;
  width: 44px;
  height: 44px;
  margin: 0;
  background: none;
  box-shadow: none;
  transform: none;
  border: 0;
  touch-action: manipulation;
}

.detail-hero-area {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  align-self: start;
  gap: 8px;
  padding: 0;
  min-width: 0;
}

.hero-side-deco {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 80px;
  flex-direction: column;
  align-items: center;
  justify-content: space-around;
  padding: 10px 0;
  pointer-events: none;
  z-index: 1;
  display: none;
}

.hero-side-l {
  left: 24px;
}

.hero-side-r {
  right: 10px;
}

.side-sticker {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  opacity: 0.35;
  --rot: 0deg;
  filter: drop-shadow(0 1px 2px color-mix(in srgb, var(--cxx-shadow) 6%, transparent));
  animation: none;
}

.side-mini-card {
  width: 50px;
  padding: 4px;
  background: var(--cxx-panel);
  border: 1px solid var(--cxx-line);
  border-radius: 2px;
  box-shadow: 0 1px 4px var(--shadow-warm);
  text-align: center;
  font-size: 0.55em;
  color: var(--cxx-muted);
  transform: rotate(var(--rot,-3deg));
  opacity: 0.5;
  animation: none;
}

.side-mini-card .mini-heart {
  font-size: 1.8em;
  display: block;
  margin-bottom: 2px;
  animation: sparkle 3s ease-in-out infinite;
}

.side-tape {
  width: 14px;
  height: 40px;
  border-radius: 1px;
  opacity: 0.35;
  transform: rotate(var(--rot,5deg));
}

.side-stamp-mark {
  width: 42px;
  height: 42px;
  border: 2px dashed var(--cxx-line);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.5em;
  color: var(--cxx-line);
  font-weight: 800;
  letter-spacing: 0.5px;
  opacity: 0.3;
  transform: rotate(var(--rot,-8deg));
  animation: none;
}

.side-line-doodle {
  width: 40px;
  height: 20px;
  border-bottom: 2px dashed var(--cxx-raised);
  border-right: 2px dashed var(--cxx-raised);
  border-radius: 0 0 12px 0;
  opacity: 0.2;
  transform: rotate(var(--rot,3deg));
}

.hero-frame {
  position: relative;
  transition: all 0.5s;
  z-index: 2;
  border-radius: 2px;
  width: min(248px,calc(100% - 104px));
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  transform: none;
}

.hero-tape {
  position: absolute;
  opacity: 0.75;
  z-index: 5;
  overflow: hidden;
  height: 2px;
  top: 0;
  left: 0;
  width: 100%;
  transform: none;
  border-radius: 0;
  background: linear-gradient(90deg,var(--cxx-red),var(--cxx-cyan));
}

.hero-tape::after {
  content: '';
  position: absolute;
  top: 0;
  width: 30px;
  height: 100%;
  background: linear-gradient(90deg,transparent,color-mix(in srgb, var(--cxx-red-soft) 40.00%, transparent),transparent);
  animation: tapeShine 3s linear infinite;
  display: none;
}

.locked-card {
  width: 228px;
  height: 306px;
  perspective: 1200px;
  cursor: pointer;
  position: relative;
}

.locked-card-inner {
  width: 100%;
  height: 100%;
  background-size: cover;
  background-position: center;
  overflow: hidden;
  transition: transform 0.15s ease;
  transform-origin: center center;
  position: relative;
  background-color: var(--cxx-ink);
  border-radius: 1px;
}

.locked-card-inner.peek-anim {
  animation: peekFlip 0.55s cubic-bezier(0.25,0.46,0.45,0.94) forwards;
}

.locked-card-inner.shake-anim {
  animation: lockShake 0.4s ease 0.25s forwards;
}

.lock-hint {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%,-50%) scale(0);
  opacity: 0;
  pointer-events: none;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.lock-hint.show {
  animation: lockFade 1.2s ease forwards;
}

.lock-hint-icon {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid var(--cxx-line);
  background: var(--cxx-ink);
  border-color: var(--cxx-red);
  border-radius: 2px;
  box-shadow: none;
}

.lock-hint-icon svg {
  width: 16px;
  height: 16px;
  fill: var(--cxx-red);
}

.lock-hint-text {
  font-size: 0.6em;
  padding: 2px 10px;
  font-weight: 700;
  letter-spacing: 1px;
  white-space: nowrap;
  text-shadow: 0 1px 2px color-mix(in srgb, var(--cxx-shadow) 10%, transparent);
  color: var(--cxx-text);
  background: var(--cxx-panel);
  border: 1px solid var(--cxx-red);
  border-radius: 2px;
}

.cat-switch {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 4px;
  margin: 12px 0 4px;
}

.cat-btn {
  font-weight: 700;
  border-radius: 11px;
  border: 1.5px solid var(--cxx-line);
  background: var(--cxx-panel);
  color: var(--cxx-text);
  cursor: pointer;
  font-family: var(--cxx-font-ui);
  letter-spacing: 1px;
  transition: all .25s ease;
  box-shadow: 0 1px 3px var(--shadow-warm);
  user-select: none;
  flex: 1;
  padding: 8px 5px;
  font-size: 12px;
  text-align: center;
}

.cat-btn.on {
  background: var(--cxx-cyan);
  border-color: var(--cxx-cyan);
  color: var(--cxx-panel);
  box-shadow: 0 2px 6px var(--shadow-rose);
}

.cat-btn:not(.on):hover {
  border-color: var(--cxx-red-soft);
  color: var(--cxx-red);
}

.cat-empty {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  z-index: 9;
}

.cat-empty-ico {
  width: 38px;
  height: 38px;
  background: color-mix(in srgb, var(--cxx-red-soft) 92.00%, transparent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid var(--cxx-line);
  box-shadow: 0 2px 10px color-mix(in srgb, var(--cxx-red) 25.00%, transparent);
}

.cat-empty-ico svg {
  width: 16px;
  height: 16px;
  fill: var(--cxx-red);
}

.cat-empty-txt {
  font-size: .6em;
  color: var(--cxx-panel);
  background: color-mix(in srgb, var(--cxx-red) 80.00%, transparent);
  padding: 2px 10px;
  border-radius: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  white-space: nowrap;
  text-shadow: 0 1px 2px color-mix(in srgb, var(--cxx-shadow) 10%, transparent);
}

.hero-name-area {
  position: absolute;
  bottom: 0;
  left: 0;
  width: 100%;
  text-align: center;
  pointer-events: none;
  background: linear-gradient(transparent,color-mix(in srgb, var(--cxx-ink) 92.94%, transparent));
  padding: 36px 12px 14px;
}

.hero-name {
  font-size: 1.35em;
  font-weight: 900;
  text-shadow: 0 2px 8px color-mix(in srgb, var(--cxx-shadow) 30%, transparent);
  font: 600 20px var(--cxx-ui);
  color: var(--cxx-text);
  letter-spacing: .08em;
}

.hero-sub {
  font-size: 0.68em;
  margin-top: 2px;
  letter-spacing: 1px;
  color: var(--cxx-red-soft);
}

.hero-caption {
  text-align: center;
  font-size: 13px;
  padding: 4px 0 0;
  font-style: normal;
  color: var(--cxx-muted);
  font: 13px/1.7 var(--cxx-ui);
  letter-spacing: .03em;
}

.mag-btn-d {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 30px;
  height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: all 0.4s cubic-bezier(0.34,1.56,0.64,1);
  background: var(--cxx-ink);
  border: 1px solid var(--cxx-line);
  border-radius: 2px;
  color: var(--cxx-cyan);
  box-shadow: none;
}

.mag-btn-d:hover {
  transform: scale(1.15) rotate(10deg);
  background: var(--cxx-selected-panel);
  border-color: var(--cxx-cyan);
  box-shadow: none;
}

.mag-btn-d svg {
  width: 13px;
  height: 13px;
  fill: var(--cxx-red);
}

.detail-notebook {
  flex: 1;
  display: flex;
  flex-direction: column;
  position: relative;
  border-radius: 2px;
  align-self: start;
  margin: 0;
  padding: 0;
  min-width: 0;
  min-height: 160px;
  border: 0;
  border-left: 1px solid var(--cxx-line);
  background: none;
  box-shadow: none;
  overflow: visible;
}

.detail-notebook::before {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  background: repeating-linear-gradient(180deg,transparent 0 27px,color-mix(in srgb, var(--cxx-red) 11.00%, transparent) 27px 28px);
  opacity: 1;
  display: none;
}

.detail-notebook::after {
  content: '';
  position: absolute;
  left: 32px;
  top: 0;
  bottom: 0;
  width: 1px;
  pointer-events: none;
  z-index: 1;
  background: var(--cxx-red);
  opacity: .6;
  display: none;
}

.nb-watermark {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 65%;
  height: 80%;
  background-size: contain;
  background-repeat: no-repeat;
  background-position: right bottom;
  pointer-events: none;
  z-index: 0;
  mix-blend-mode: normal;
  opacity: .035;
}

.nb-ticker {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  overflow: hidden;
  position: relative;
  z-index: 2;
  background: none;
  border: 0;
  border-bottom: 1px solid var(--cxx-line);
  padding: 8px 18px;
  height: auto;
}

.nb-ticker-scroll {
  white-space: nowrap;
  padding-left: 10px;
  display: block;
  animation: none;
  transform: none;
  width: auto;
}

.nb-ticker-item {
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  letter-spacing: 0.3px;
  white-space: normal;
  overflow-wrap: anywhere;
  font: 13px/1.8 var(--cxx-ui);
  color: var(--cxx-muted);
  padding: 0;
}

.nb-ticker-item::before {
  margin-right: 8px;
  font-size: 13px;
  content: '▸';
  color: var(--cxx-red);
}

.nb-thought-area {
  position: relative;
  z-index: 2;
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow-y: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--cxx-line) transparent;
  padding: 22px 18px;
}

.nb-thought-area::-webkit-scrollbar {
  width: 4px;
}

.nb-thought-area::-webkit-scrollbar-thumb {
  background: var(--cxx-line);
  border-radius: 10px;
}

.thought-entry {
  font-size: 16px;
  line-height: 1.85;
  position: relative;
  padding-left: 16px;
  color: var(--cxx-text);
  overflow-wrap: anywhere;
}

.thought-entry::before {
  position: absolute;
  left: 0;
  top: 0;
  font-size: 0.9em;
  content: '›';
  color: var(--cxx-cyan);
}

.thought-entry-label {
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  display: flex;
  align-items: center;
  gap: 4px;
  font-family: var(--cxx-font-mono);
  margin-bottom: 12px;
  font: 13px/1.5 var(--cxx-ui);
  color: var(--cxx-red);
  letter-spacing: .14em;
}

.nb-corner-deco {
  position: absolute;
  bottom: 8px;
  right: 10px;
  font-size: 1.4em;
  opacity: 0.1;
  transform: rotate(12deg);
  pointer-events: none;
  z-index: 0;
  display: none;
}

.nb-absent {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px;
  text-align: center;
  gap: 8px;
  flex: 1;
}

.nb-absent-ico {
  font-size: 1.8em;
  opacity: 0.25;
  animation: none;
}

.nb-absent-txt {
  font-size: 0.82em;
  font-weight: 700;
  color: var(--cxx-muted);
}

.nb-absent-sub {
  font-size: 13px;
  color: var(--cxx-muted);
}

.img-modal {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 9999;
  justify-content: center;
  align-items: center;
  backdrop-filter: blur(6px);
  background: color-mix(in srgb, var(--cxx-ink) 94%, transparent);
}

.img-modal.on {
  display: flex;
  animation: fadeIn 0.3s ease;
}

.img-modal-pic {
  max-width: 85%;
  max-height: 85%;
  border: 6px solid var(--cxx-panel);
  border-color: var(--cxx-line);
  border-width: 2px;
  border-radius: 2px;
  box-shadow: 0 20px 60px color-mix(in srgb, var(--cxx-shadow) 50%, transparent);
}

.img-modal-x {
  position: absolute;
  top: 24px;
  right: 30px;
  font-size: 24px;
  cursor: pointer;
  width: 42px;
  height: 42px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 3px 10px var(--shadow-warm);
  border: 1px solid var(--cxx-line);
  transition: all 0.3s;
  background: var(--cxx-ink);
  border-color: var(--cxx-line);
  border-radius: 2px;
  color: var(--cxx-cyan);
}

.img-modal-x:hover {
  transform: scale(1.1);
}

@media (max-width:560px) {
  .diary-stage {
    height: auto;
  }

  .diary::after {
    width: 20px;
  }

  .binding-holes {
    left: 4px;
  }

  .nb-thought-area {
    padding-left: 26px;
  }

  .detail-notebook {
    margin-left: 32px;
  }

  .detail-notebook::after {
    left: 24px;
  }

  .hero-frame {
    width: 200px;
  }

  .locked-card {
    width: 188px;
    height: 252px;
  }

  .char-card {
    padding: 8px 10px;
    gap: 10px;
  }

  .card-polaroid {
    width: 42px;
    height: 50px;
  }

  .hero-side-deco {
    width: 50px;
  }

  .side-sticker {
    font-size: 16px;
  }

  .side-mini-card {
    width: 38px;
  }
}

:root {
  --shadow-warm: color-mix(in srgb, var(--cxx-shadow) 20%, transparent);
  --shadow-rose: color-mix(in srgb, var(--cxx-red) 10.00%, transparent);
  --cxx-ui: var(--cxx-font-ui);
  --cxx-mono: var(--cxx-font-mono);
}

.b-hole {
  width: 4px;
  height: 4px;
  border: 0;
  border-radius: 1px;
  background: var(--cxx-red);
  box-shadow: none;
}

.washi-title::before {
  content: '';
}

.washi-title::after {
  content: '';
}

.char-card:hover {
  box-shadow: inset 2px 0 var(--cxx-cyan),0 6px 14px color-mix(in srgb, var(--cxx-shadow) 20%, transparent);
  background: var(--cxx-raised);
  border-color: color-mix(in srgb, var(--cxx-red) 50.20%, transparent);
  transform: none;
}

.char-card:hover::before {
  background: var(--cxx-cyan);
  width: 100%;
}

.char-card:focus-visible::before {
  background: var(--cxx-cyan);
  width: 100%;
}

.char-card:nth-child(even) .card-polaroid {
