.cxx-native-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0;
  min-height: 54px;
  padding: 0 8px;
  background: var(--cxx-ink);
  border-top: 1px solid var(--cxx-line);
  border-bottom: 1px solid var(--cxx-line);
  position: relative;
}

.cxx-native-toolbar::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--cxx-red);
  pointer-events: none;
}

.cxx-native-toolbar button {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 44px;
  padding: 8px;
  color: var(--cxx-text);
  background: none;
  border: 0;
  border-radius: 0;
  font: 16px var(--cxx-ui);
  letter-spacing: .08em;
  white-space: nowrap;
  cursor: pointer;
  touch-action: manipulation;
}

.cxx-native-toolbar button:first-child {
  flex: 1 0 auto;
  text-align: left;
}

.cxx-native-toolbar button:last-child {
  border-left: 1px solid var(--cxx-line);
}

.cxx-native-toolbar button:hover {
  background: color-mix(in srgb, var(--cxx-red-soft) 2.35%, transparent);
  color: var(--cxx-red-soft);
}

.cxx-native-toolbar button:disabled {
