\x3cscript>
document.addEventListener('DOMContentLoaded', () => {
    const optionsDataSource = document.getElementById('options-data');
    const container = document.getElementById('button-container');
    const card = document.getElementById('optionsCard');
    const headerSub = card ? card.querySelector('.header-sub') : null;
    const smugFace = document.getElementById('smugFace');

    if (!optionsDataSource || !container) return;

    function updateOptions236(optionsText) {
    const lines = optionsText.trim().split('\n');

    container.innerHTML = '';

    lines.forEach((line, index) => {
        const trimmedLine = line.trim();
        if (!trimmedLine) return;

        const match = trimmedLine.match(/^\s*(\d+)\.\s*(.*)$/);
        let actionText = trimmedLine;
        if (match) {
            actionText = match[2].trim();
        }

        const button = document.createElement('button');
        button.className = 'option-btn';
        if (match) {
            const key = document.createElement('span');
            key.className = 'option-key';
            key.setAttribute('aria-hidden', 'true');
            key.textContent = match[1];
            button.append(key, document.createTextNode(actionText));
        } else button.textContent = trimmedLine;
        button.setAttribute('data-action', actionText);
        button.style.animationDelay = (index * 0.05) + 's';

        button.addEventListener('click', (event) => {
            event.stopPropagation();
            if(window.frameElement?.dataset.cxxReady!=='1')return;
            let textToAppend = button.getAttribute('data-action');
            if (!textToAppend) return;

            try {
                const input = window.parent.document.querySelector('#send_textarea');
                if (input) {
                    const currentValue = input.value.trim();
                    input.value = currentValue ? `${currentValue}\n${textToAppend}` : textToAppend;
                    input.dispatchEvent(new Event('input', { bubbles: true }));
                }
            } catch (error) {
                console.error('SillyTavern Regex Error:', error);
            }

            document.querySelectorAll('#button-container .option-btn').forEach(b => b.classList.remove('active'));
            button.classList.add('active');

            if (smugFace) {
                smugFace.classList.remove('show');
                void smugFace.offsetWidth;
                smugFace.classList.add('show');
            }
        });

        container.appendChild(button);
    });

    }
    window.Cxx236ComponentUpdate=value=>{updateOptions236(value);document.querySelectorAll('.option-btn').forEach(b=>b.disabled=window.frameElement?.dataset.cxxReady!=='1');};
    updateOptions236(window.Cxx236InitialValue || optionsDataSource.innerHTML);

    if (card && headerSub) {
        card.addEventListener('toggle', () => {
            if (card.open) {
                headerSub.innerHTML = '\x3cspan class="header-dot">\x3c/span>选一个吧~';
            } else {
                headerSub.innerHTML = '\x3cspan class="header-dot">\x3c/span>点击展开选项';
            }
        });
    }
});
\x3c/script>

