nav select {
  margin-left: auto;
  max-width: 48%;
}

.memory-pages {
  display: grid;
  grid-template-columns: minmax(0,1fr);
  grid-template-rows: minmax(0,1fr);
  min-height: 0;
  flex: 1;
  overflow: hidden;
}

main {
  grid-area: 1 / 1;
  padding: 12px 20px 24px;
  overflow: auto;
  min-height: 0;
  flex: 1;
  overscroll-behavior: contain;
  scroll-padding: 16px;
}

button {
  font: inherit;
  color: inherit;
  border: 1px solid var(--line);
  background: var(--cxx-raised);
  border-radius: 0;
  padding: 9px 12px;
  min-height: 44px;
  max-width: 100%;
  cursor: pointer;
  margin: 4px 6px 4px 0;
}

input {
  font: inherit;
  color: inherit;
  border: 1px solid var(--line);
  background: var(--cxx-raised);
  border-radius: 0;
  padding: 9px 12px;
  min-height: 44px;
  max-width: 100%;
}

select {
  font: inherit;
  color: inherit;
  border: 1px solid var(--line);
  background: var(--cxx-raised);
  border-radius: 0;
  padding: 9px 12px;
  min-height: 44px;
  max-width: 100%;
  margin-left: 8px;
}

textarea {
  font: inherit;
  color: inherit;
  border: 1px solid var(--line);
  background: var(--cxx-raised);
  border-radius: 0;
  padding: 9px 12px;
  min-height: 44px;
  max-width: 100%;
  width: 100%;
}

button:disabled {
  opacity: .5;
  cursor: default;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: -2px;
}

input:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: -2px;
}

select:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: -2px;
}

textarea:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: -2px;
}

summary:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: -2px;
}

input[type=checkbox] {
  min-height: 24px;
  width: 24px;
  height: 24px;
  vertical-align: middle;
  margin-right: 10px;
  accent-color: var(--cyan);
}

label:has(input[type=checkbox]) {
  display: flex;
  align-items: center;
  min-height: 44px;
  cursor: pointer;
}

input[type=search] {
  width: 100%;
}

label {
  display: block;
  margin: 10px 0;
}

input[type=number] {
  margin-left: 8px;
}

article {
  border-top: 1px solid var(--line);
  padding: 14px 0;
}

section {
  border-top: 1px solid var(--line);
  padding: 14px 0;
}

h3 {
  margin: 6px 0;
  font-size: 18px;
  color: var(--cxx-heading);
}

h4 {
  margin: 0;
  font-size: 16px;
  color: var(--red);
}

p {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

pre {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font: 16px/1.6 var(--cxx-font-ui);
  max-height: 260px;
  overflow: auto;
}

blockquote {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  margin: 10px 0;
  padding: 8px 12px;
  border-left: 2px solid var(--cyan);
  background: var(--cxx-panel);
}

summary {
  cursor: pointer;
  min-height: 44px;
  padding: 10px 0;
}

small {
  color: var(--cxx-muted);
  font-size: 14px;
}

.muted {
  color: var(--cxx-muted);
}

summary small {
  display: block;
}

.memory-title {
  font-size: 16px;
  display: block;
}

.badge {
  display: inline-block;
  color: var(--cyan);
  border: 1px solid var(--line);
  padding: 2px 8px;
  margin-top: 6px;
  font-size: 13px;
}

.badge[data-mode=permanent] {
  color: var(--cxx-yellow-soft);
}

.badge[data-mode=excluded] {
  color: var(--cxx-muted);
}

.memory-detail {
  padding: 0 12px 8px;
  border-left: 1px solid var(--line);
}

.memory-tools {
  display: flex;
  align-items: center;
  gap: 12px;
}

.memory-tools>input {
  flex: 1;
  min-width: 0;
}

.memory-tools label {
  flex: none;
}

.range {
  display: flex;
  gap: 16px;
}

.range input {
  width: 110px;
}

.book {
  padding: 10px;
  border-left: 2px solid var(--cyan);
}

progress {
  width: 100%;
  height: 10px;
  accent-color: var(--red);
}

.notice {
  color: var(--cxx-yellow-soft);
}

.notice:empty {
  display: none;
}

[role=status]:empty {
  display: none;
}

.panel-status {
  margin: 0;
  padding: 6px 20px;
  color: var(--cyan);
  font-size: 14px;
  flex: none;
}

.undo {
  margin: 0;
  padding: 6px 20px;
  color: var(--cyan);
  font-size: 14px;
  flex: none;
}

.undo:empty {
  display: none;
}

.empty {
  padding: 20px 0;
}

button:active:not(:disabled):not(:focus-visible) {
  background: var(--cxx-raised);
  transform: scale(.98);
}

@media (hover:hover) and (pointer:fine) {
  button:hover:not(:disabled) {
    border-color: var(--cyan);
  }

  button:not(:focus-visible) {
    transition: transform 140ms cubic-bezier(.23,1,.32,1);
  }

  button:active:not(:disabled) {
    transition-duration: 0s;
  }
}

@media (max-width:600px) {
  .context-table {
    min-width: 0;
  }

  .context-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  .context-table tbody {
    display: grid;
    gap: 16px;
  }

  .context-table tr {
    display: grid;
    grid-template-columns: repeat(2,minmax(0,1fr));
    border: 1px solid var(--line);
  }

  .context-table td {
    min-width: 0;
    overflow-wrap: anywhere;
  }

  .context-table td:first-child {
    grid-column: 1/-1;
    width: auto;
    min-width: 0;
  }

  .context-table td[data-label]::before {
    content: attr(data-label);
    display: block;
    color: var(--cyan);
    font-size: 14px;
  }

  dialog {
    width: 100vw;
    max-width: 100vw;
    height: 100dvh;
    max-height: 100dvh;
    border-left: 0;
    border-right: 0;
  }

  header {
    padding: 10px 14px 4px;
  }

  header h2 {
    font-size: 19px;
  }

  nav {
    padding: 0 14px 8px;
    gap: 4px;
  }

  nav button {
    padding: 8px 14px;
    margin-right: 2px;
  }

  nav select {
    font-size: 16px;
  }

  main {
    padding: 8px 14px max(18px,env(safe-area-inset-bottom));
  }

  .memory-tools {
    display: block;
  }

  .memory-tools label {
    display: flex;
    align-items: center;
  }

  .memory-tools select {
    flex: 1;
  }

  .range {
    gap: 8px;
  }

  .range label {
    flex: 1;
  }

  .range input {
    width: 100%;
    margin: 4px 0;
  }

  input {
    font-size: 16px;
  }

  select {
    font-size: 16px;
  }

  textarea {
    font-size: 16px;
  }

  .panel-status {
    padding: 6px 14px;
  }

  .undo {
    padding: 6px 14px;
  }

  header button {
    margin-right: 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  button {
    transition: none!important;
    transform: none!important;
  }
}
